COLLDATA("tadabburar","ar",[[314,"§طه\nwords\nاليَمِّنَهرِ النِّيلِ.\nيَكفُلُهُيُرَبِّيهِ، وَيُرضِعُهُ.\nتَقَرَّ عَينُهَاتَطِيبُ نَفسُهَا.\nوَفَتَنَّاكَ فُتُونًاابتَلَينَاكَ ابتِلاَءً.\nعَلَى قَدَرٍعَلَى وَفقِ الوَقتِ المُقَدَّرِ لِإِرسَالِكَ.\nوَلاَ تَنِيَالاَ تَفتُرَا وَلاَ تَضعُفَا.\nيَفرُطَيُعَاجِلَنَا بِالعُقُوبَةِ.\ndeeds\nاسأل الله أن يلقي عليك محبة منه، وأن يضع لك القبول في الأرض، كما أنعم على أوليائه.\nمر بمعروف، وانه عن منكر بحكمة وعلم، ولا تخف.\nاحتسب الأجر في حضور مجلس بنية تعلم الحوار والجدال في الدعوة إلى الله سبحانه.\nguid\nأمر موسى وهارون ألا يفترا عن ذكر الله وهما ذاهبان لدعوة فرعون؛ لأن ذكر الله يهون الأمور على الإنسان.\nالكلام اللين، والخطاب الهين في الدعوة إلى الله أقرب للإجابة وأقوى في الحجة.\nمعية الله وحفظه لأوليائه وأهل طاعته.\nrefl\nوَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ ٣٩\nقال ابن عباس -رضي الله عنهما-: \"أحبه الله، وحببه إلى خلقه\"، وقال ابن زيد: \"جعلت من رآك أحبك، حتى أحبك فرعون، فسلمت من شره، وأحبتك آسية بنت مزاحم فتبنتك\". القرطبي:١٤/٥٨.\nمن الذي يضع للعبد المحبة في قلوب الخلق؟\nوَٱصۡطَنَعۡتُكَ لِنَفۡسِي ٤١\nإذا كان الحبيب إذا أراد اصطناع حبيبه من المخلوقين، وأراد أن يبلغ من الكمال المطلوب له ما يبلغ، يبذل غاية جهده، ويسعى نهاية ما يمكنه في إيصاله لذلك، فما ظنك بصنائع الرب القادر الكريم، وما تحسبه يفعل بمن أراده لنفسه، واصطفاه من خلقه؟! السعدي:٥٠٦.\nكيف تدل الآية على فضل موسى -عليه السلام-؟\nٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي ٤٢\nيقول: ولا تضعفا في أن تذكراني فيما أمرتكما ونهيتكما؛ فإن ذكركما إياي يقوي عزائمكما، ويثبت أقدامكما؛ لأنكما إذا ذكرتماني ذكرتما منِّي عليكما نعمًا جمةً، ومننًا لا تحصى كثرةً. الطبري:١٨/٣١٢.\nما الفوائد التي يجنيها الداعية من ذكر الله؟\nٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ٤٣ فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ ٤٤\nقال يحيى بن معاذ في هذه الآية: \"هذا رفقك بمن يقول: أنا الإله، فكيف رفقك بمن يقول: أنت الإله؟!\". القرطبي:١٤/٦٦.\nاذكر مظهرًا من مظاهر رحمة الله تعالى بعباده من خلال الآية.\nفَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ ٤٤\nإذ المقصود من دعوة الرسل حصول الاهتداء، لا إظهار العظمة وغلظة القول بدون جدوى، فإذا لم ينفع اللين مع المدعوّ، وأعرض واستكبر؛ جاز في موعظته الإغلاظ معه. ابن عاشور:١٦/٢٢٥.\nما المقصود بالحكمة في دعوة الناس؟\nقَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ ٤٩\nوأعرض عن أن يقول: فمن ربي؟ إلى قوله: ﴿فَمَن رَّبُّكُمَا﴾ إعراضًا عن الاعتراف بالمربوبية ولو بحكاية قولهما؛ لئلَّا يقع ذلك في سمع أتباعه وقومه، فيحسبوا أنه متردد في معرفة ربّه، أو أنه اعترف بأنّ له ربًّا. ابن عاشور:١٦/٢٣٢.\nلماذا لم يقل فرعون: فمن ربي، وإنَّما قال: ﴿فَمَن رَّبُّكُمَا﴾ ؟\nقَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ ٥٠\nقال الحسن وقتادة: \"أعطى كل شيء صلاحه، وهداه لما يصلحه\". البغوي:٣/١٢٤.\nبيّن نعمة الله تعالى على خلقه بإعطائهم وهدايتهم."],[315,"§طه\nwords\nمَهدًامُيَسَّرَةً لِلاِنتِفَاعِ بِهَا.\nسُبُلًاطُرُقًا.\nلِأُولِي النُّهَىلِذَوِي العُقُولِ السَّلِيمَةِ.\nسُوىًمُستَوِيًا مُعتَدِلًا.\nيَومُ الزِّينَةِيَومُ العِيدِ.\nفَيُسحِتَكُمفَيَستَأصِلَكُم.\nبِطَرِيقَتِكُمُ المُثلَىطَرِيقَةِ السِّحرِ العَظِيمَةِ.\ndeeds\nألق كلمة، أو أرسل رسالة عن خطر السحر.\nانصح أنت وبعض زملائك ساحرًا أو مشعوذًا أو عرّافًا أو مجاهرًا بمعصية، وادعه إلى التوبة، وذكره بعظيم ذنبه وخطورته، وعظيم مغفرة الله ورحمته.\nانكر منكرًا رأيته بين زملائك.\nguid\nمشروعية المناظرة لإظهار الحق وإبطال الباطل.\nلا تناظر إلا عن علم وبصيرة وشهود.\nالدعاة وطلبة العلم أولى في التعاون لإيصال الدعوة إلى الآخرين وتبليغ الدين.\nrefl\nٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ ٥٣\n﴿ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدًا﴾ أي: فراشًا، وانظر كيف وصف موسى ربه تعالى بأوصاف لا يمكن فرعون أن يتصف بها؛ لا على وجه الحقيقة، ولا على وجه المجاز، ولو قال له: هو القادر، أو الرازق، وشبه ذلك؛ لأمكن فرعون أن يغالطه، ويدعي ذلك لنفسه. ابن جزي:٢/٢٠.\nعلى الداعية المؤثر أن يكون مقنعًا في حجته، كيف تستفيد ذلك من حوار موسى مع فرعون؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ ٥٤\n﴿لَأٓيَٰتٍ لِّأُوْلِي ٱلنُّهَىٰ﴾: لذوي العقول؛ واحدتها نهية؛ سميت نهية لأنها تنهى صاحبها عن القبائح والمعاصي. البغوي:٣/١٢٦.\nلم سمى الله تعالى أصحاب العقول أولي النهى؟\nكُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ ٥٤\nوخص الله أولي النهى بذلك؛ لأنهم المنتفعون بها، الناظرون إليها نظر اعتبار، وأمَّا من عداهم فإنهم بمنزلة البهائم السارحة، والأنعام السائمة؛ لا ينظرون إليها نظر اعتبار، ولا تنفذ بصائرهم إلى المقصود منها، بل حظهم حظ البهائم؛ يأكلون ويشربون، وقلوبهم لاهية، وأجسامهم معرضة. السعدي:٥٠٧.\nمن المستفيد من آثار نعمة الله وقدرته، المدرك لمقاصدها؟\nقَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ ٥٧\nزعم أن هذه الآيات التي أراه إياها موسى سحر وتمويه المقصود منها إخراجهم من أرضهم والاستيلاء عليها؛ ليكون كلامه مؤثرًا في قلوب قومه؛ فإن الطباع تميل إلى أوطانها، ويصعب الخروج منها ومفارقتها. السعدي:٥٠٨.\nلماذا اختار فرعون أن يتهم موسى بأنه جاء لإخراج فرعون وقومه من أرضهم؟\nقَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى ٥٩ فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ ٦٠\nوإنَّما واعدهم ذلك اليوم ليكون علو كلمة الله، وظهور دينه، وكبت الكافر، وزهوق الباطل على رءوس الأشهاد، وفي المجمع الغاصّ؛ لتقوى رغبة من رغب في الحق، ويكلّ حد المبطلين وأشياعهم، ويكثر المحدث بذلك الأمر العلم في كل بدو وحضر، ويشيع في جمع أهل الوبر والمدر. القرطبي:١٤/٨٦.\nما السر في اختيار موسى -عليه السلام- لمواعدة بني إسرائيل يوم عيد واجتماع عام؟\nفَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ ٦٠\nومعنى جمع الكيد: تدبير أسلوب مناظرة موسى، وإعداد الحيل لإظهار غلبة السحرة عليه، وإقناع الحاضرين بأنّ موسى ليس على شيء. وهذا أسلوب قديم في المناظرات؛ أن يسعى المناظر جهده للتشهير ببطلان حجّة خصمه بكلّ وسائل التلبيس والتشنيع والتشهير، ومبادأته بما يفتّ في عضده، ويشوش رأيه؛ حتّى يذهب منه تدبيره. ابن عاشور:١٦/٢٤٧.\nذكرت الآية الكريمة أسلوبًا من الأساليب الفرعونية في المناظرات، فما هو؟\nفَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ\nليكون أمكن لعملكم، وأهيب لكم في القلوب، ولئلَّا يترك بعضكم بعض مقدوره من العمل. السعدي:٥٠٨.\nلماذا تناصح السحرة فيما بينهم أن يأتوا صفًا؟"],[316,"§طه\nwords\nفَأَوجَسَفَشَعَرَ، وَأَحَسَّ فِي نَفسِهِ.\nتَلقَفتَبتَلِع.\nمِن خِلاَفٍمُخَالِفًا بَينَ الأَيدِي وَالأَرجُلِ؛ فَيَقطَعُ يَدًا مِن جِهَةٍ، وَرِجلًا مِن جِهَةٍ أُخرَى.\nنُؤثِرَكَنُفَضِّلَكَ.\nفَطَرَنَاخَلَقَنَا وَأَبدَعَنَا.\nفَاقضِفَافعَل وَاحكُم.\ndeeds\nأرسل رسالة تحذر فيها من السحر وأهله.\nقل: \"اللهم يا مقلب القلوب ثبت قلبي على دينك\".\nأرسل رسالة تبشر فيها أنه ليس كل ما يهدد به الطغاة يقع؛ لأن الحكم لله أولًا وآخرًا.\nguid\nمن علامة ضعف عقول الطغـاة توعـد أهل الحق بالقوة والبطش.\nإذا واجه الداعية تهديدًا أو بطشًا قارن بينه وبين ما ينتظره في الآخرة؛ فهان عليه وصبر.\nكلما اشتد الابتلاء قرب الفرج.\nrefl\nقَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ ٦٥ قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ ٦٦\nخيروه، موهمين أنهم على جزم من ظهورهم عليه بأي حالة كانت. السعدي:٥٠٨.\nثقة أهل الباطل بأنفسهم لا تزعزع ثقة المؤمن بربه، وضح ذلك من خلال الآية.\nفَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ ٦٧\nكما هو مقتضى الطبيعة البشرية، وإلا فهو جازم بوعد الله ونصره. السعدي:٥٠٨.\nما سبب الخوف الذي وقع من موسى؟ وهل كان شاكًا في وعد الله؟\nوَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ ٦٩\nيعم نفي جميع أنواع الفلاح عن الساحر، وأكد ذلك بالتعميم في الأمكنة بقوله: ﴿حَيۡثُ أَتَىٰ﴾، وذلك دليل على كفره؛ لأن الفلاح لا ينفى بالكلية نفيًا عامًّا إلا عمن لا خير فيه؛ وهو الكافر. الشنقيطي:٤/٣٩.\nما وجه نفي الفلاح عن الساحر؟\nقَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ ٧١\nولما رأى فرعون إيمان السحرة تغيّظ ورام عقابهم، ولكنه علم أنّ العقاب على الإيمان بموسى بعد أن فتح باب المناظرة معه نكث لأصول المناظرة، فاختلق -للتشفّي من الذين آمنوا- علّة إعلانهم الإيمان قبل استئذانِ فرعون، فعدّ ذلك جرأة عليه. ابن عاشور:١٦/٢٦٣.\nمن صفات المغلوب اختلاق الأعذار الواهية، بيِّن ذلك من الآيات الكريمة\nقَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ ٧٢\nأظهروا استخفافهم بوعيده وبتعذيبه؛ إذ أصبحوا أهل إيمان ويقين، وكذلك شأن المؤمنين بالرسل إذا أشرقت عليهم أنوار الرسالة؛ فسرعان ما يكون انقلابهم عن جهالة الكفر وقساوته إلى حكمة الإيمان وثباته. ابن عاشور:١٦/٢٦٦.\nبيّن حال المؤمنين إذا أشرقت عليهم أنوار الرسالة.\nقَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ ٧٢\nوفي هذا الكلام من السحرة دليل على أنه ينبغي للعاقل أن يوازن بين لذات الدنيا ولذات الآخرة، وبين عذاب الدنيا وعذاب الآخرة. السعدي:٥٠٩.\nإذا واجهتك لذة من لذات الدنيا المحرمة؛ فإن هذه الآية تدلك على طريقة تتخلص بها من هذه الشهوة، بيِّن ذلك.\nإِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ ٧٤\nفلا ينتفع بحياته، ولا يستريح بموته، وقيل: نفس الكافر معلقة في حنجرته، كما أخبر الله تعالى عنه، فلا يموت بفراقها، ولا يحيا باستقرارها. القرطبي:١٤/١٠٧.\nبيّن شدة عذاب الله تعالى للكافر في كونه بين الحياة والموت."],[317,"§طه\nwords\nأَسرِاُخرُج لَيلًا.\nدَرَكًاإِدرَاكًا.\nالمَنَّطَعَامًا؛ كَالعَسَلِ.\nوَالسَّلوَىطَيرًا؛ كَالسُّمَانَى.\nعَلَى أَثَرِيخَلفِي سَوفَ يَلحَقُونَ بِي.\nبِمَلكِنَابِاختِيَارِنَا وَقُدرَتِنَا.\nمِن زِينَةِ القَومِمِن حُلِيِّ قَومِ فِرعَونَ.\ndeeds\nقل: \"يا رب لك الحمد، أنجيتني من بلاء كذا، حفظتني من فتنة كذا، فرجت عني كربة كذا وكذا\".\nاستعذ بالله من أسباب غضبه.\nسمّ الله تعالى عند الأكل، واحمده بعده، واحذر الإسراف والمباهاة.\nguid\nكن على يقين بوعد الله تعالى، ولا تخف من الباطل وأهله.\nتحريم الإسراف والظلم، وكفر النعم.\nمن صفات الأنبياء: الغضب والحزن على وقوع معصية أو ترك طاعة.\nrefl\nوَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ ٧٧\nاقتصر على وعده دون بقية قومه لأنه قدوتهم، فإذا لم يخف هو تشجعوا وقوي يقينهم. ابن عاشور:١٦/٢٧٠.\nلماذا جاء الوعد في الآية الكريمة بعدم الخوف من الدرك لموسى -عليه السلام- دون قومه؟\nوَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ ٨١\nقال ابن عباس -رضي الله عنهما-: \"لا تظلموا\". وقال الكلبي: \"لا تكفروا النعمة فتكونوا ظالمين طاغين\". وقيل: لا تنفقوا في معصيتي. وقيل: لا تتقووا بنعمتي على معاصيَّ. البغوي:٣/١٣٤.\nمتى يصل العبد إلى حد الطغيان الذي تتنزل بسببه العقوبة؟\nوَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ ٨٢\nالأسباب [أسباب المغفرة] كلها منحصرة في هذه الأشياء: فإن التوبة تجُبُّ ما قبلها، والإيمان والإسلام يهدم ما قبله، والعمل الصالح الذي هو الحسنات يذهب السيئات، وسلوك طريق الهداية بجميع أنواعها: من تعلم علم، وتدبر آية أو حديث؛ حتى يتبين له معنى من المعاني يهتدي به، ودعوة إلى دين الحق، ورد بدعة أو كفر أو ضلالة، وجهاد، وهجرة، وغير ذلك من جزئيات الهداية، كلها مكفرات للذنوب، محصلات لغاية المطلوب. السعدي:٥١١.\nذكرت الآية ثلاثة أسباب للمغفرة، فما هي ؟\nوَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ ٨٣\nموسى -عليه السلام- لمَّا أمره الله أن يسير هو وبنو إسرائيل إلى الطور، تقدم هو وحده مبادرة إلى أمر الله، وطلبًا لرضاه، وأمر بني إسرائيل أن يسيروا بعده، واستخلف عليهم أخاه هارون، فأمرهم السامريّ حينئذ بعبادة العجل. ابن جزي:٢/٢٣.\nما الذي أعجل موسى -عليه السلام-؟\nوَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ ٨٤\nأي: عجلت إلى الموضع الذي أمرتني بالمصير إليه؛ لترضى عني. القرطبي:١٤/١١٧.\nما الصفة التي تزيد رضا الله عن المتعبد؟\nفَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ\nأي: بعد ما أخبره تعالى بذلك في غاية الغضب والحنق عليهم؛ هو فيما هو فيه من الاعتناء بأمرهم، وتسلُّم التوراة التي فيها شريعتهم؛ وهذا شرف لهم، وهم قوم قد عبدوا غير الله. ابن كثير:٣/١٥٧.\nالأنبياء والدعاة من أشفق الناس على الأمة، وضِّح ذلك من خلال هذه الآية.\nقَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ ٨٧\nوحاصل ما اعتذر به هؤلاء الجهلة: أنهم تورعوا عن زينة القبط؛ فألقوها عنهم، وعبدوا العجل؛ فتورعوا عن الحقير، وفعلوا الأمر الكبير. الشنقيطي:٤/٨٧.\nمن خلال الآية: وضح ضرر الورع إن كان عن جهل."],[318,"§طه\nwords\nجَسَدًامُجَسَّدًا مِنَ الذَّهَبِ.\nلَهُ خُوَارٌلَهُ صَوتٌ كَصَوتِ البَقَرِ.\nلَن نَبرَحَلَن نَزَالَ.\nوَلَم تَرقُب قَولِيلَم تَحفَظ وَصِيَّتِي بِحُسنِ رِعَايَتِهِم.\nبَصُرتُرَأَيتُ أَو علمت بِبَصِيرَتي.\nلاَ مِسَاسَأَي: تَكُونَ مَنبُوذًا؛ تَقُولُ لِكُلِّ وَاحِدٍ: لاَ أَمَسُّكَ، وَلاَ تَمَسُّنِي.\ndeeds\nأنكر منكرًا بالقول والقلب إذا لم تستطع تغييره باليد.\nوفر لحيتك ولا تحلقها؛ فإنها سنة الأنبياء -عليهم الصلاة والسلام-.\nاستعذ بالله من النفس الأمارة بالسوء التي تزين المعصية.\nguid\nالعذل والعتاب لا يقطع الأخوة في الله.\nالتلطف في الرد على الغضبان، ومناداته بما يرقق قلبه من أسباب تهدئته.\nإزالة الباطل من قلوب الناس يجب أن يكون بأحكم طريقة تقنعهم ببطلانه.\nrefl\nأَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا ٨٩\nوقدم الضرّ على النفع قطعًا لعُذرهم في اعتقاد إلهيته؛ لأن عذر الخائف من الضرّ أقوى من عذر الراغب في النفع. ابن عاشور:١٦/٢٨٩.\nلماذا قدم الضر على النفع في الآية الكريمة؟\nأَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا ٨٩\nلأن ذلك محل العبرة من فقدانه صفات العاقل؛ لأنهم يَدعُونه، ويُثنون عليه، ويمجدونه، وهو ساكت، لا يشكر لهم، ولا يَعِدهم باستجابة، وشأن الكامل إذا سمع ثناء أو تلقّى طِلبة أن يجيب. ابن عاشور:١٦/٢٨٨.\nمن أدلة بطلان عبادة الأصنام والأضرحة والقبور أنها لا تجيب أصحابها؛ كيف دلت الآية الكريمة على ذلك؟\nقَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ ٩٢ أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي ٩٣\nهذا كله أصل في الأمر بالمعروف والنهي عن المنكر، وتغييره ومفارقة أهله، وأن المقيم بينهم -لاسيما إذا كان راضيًا- حكمه كحكمهم. القرطبي:١٤/١٢٤.\nما الأصل العظيم الذي يفيده كل مؤمن من هذه الآية؟\nقَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ\nترقق له بذكر الأم، مع أنه شقيقه لأبويه؛ لأن ذكر الأم هاهنا أرق وأبلغ في الحنو والعطف. ابن كثير:٣/١٥٩.\nلماذا نادى هارونُ موسى بـ (يا ابن أم) مع أنه شقيقه؟\nقَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ\nهذه الآية الكريمة بضميمة آية (الأنعام) إليها تدل على لزوم إعفاء اللحية؛ فهي دليل قرآني على إعفاء اللحية وعدم حلقها. وآية الأنعام المذكورة هي قوله تعالى: ﴿وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ...﴾ الآية [الأنعام: ٩٠]؛ ثم إنه تعالى قال بعد أن عدّ الأنبياء الكرام المذكورين: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡ﴾؛ فدل ذلك على أن هارون من الأنبياء الذين أُمِر نبيُّنا بالاقتداء بهم، وأمره بذلك أمر لنا؛ لأن أمر القدوة أمر لأتباعه. الشنقيطي:٤/٩٢.\nكيف تجعل من الآية دليلًا على وجوب إعفاء اللحية؟\nقَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ\nهذه الآية أصل في نفي أهل البدع والمعاصي وهجرانهم، وألا يخَالطوا، وقد فعل النبي ذلك بكعب بن مالك والثلاثة الذين خلفوا -رضي الله عنهم-. القرطبي:١٤/١٣٠.\nكثر في هذا الزمان دعاة البدع ودعاة الضلالة، كيف نتعامل معهم في ضوء هذه الآية؟\nوَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا ٩٧\nففعل موسى ذلك، فلو كان إلهًا لامتنع ممن يريده بأذى ويسعى له بالإتلاف، وكان قد أُشرِبَ العجل في قلوب بني إسرائيل، فأراد موسى -عليه السلام- إتلافه -وهم ينظرون- على وجه لا تمكن إعادته، بالإحراق والسحق، وذريه في اليم ونسفه؛ ليزول ما في قلوبهم من حبه، كما زال شخصه. السعدي:٥١٢.\nلماذا أزال موسى العجل بهذه الطريقة؟"],[319,"§طه\nwords\nزُرقًازُرقَ العُيُونِ مَعَ سَوَادِ وُجُوهِهِم.\nيَتَخَافَتُونَيَتَسَارُّونَ، وَيَتَهَامَسُونَ.\nأَمثَلُهُم طَرِيقَةًأَعلَمُهُم، وَأَوفَاهُم عَقلًا.\nقَاعًاأَرضًا مَلسَاءَ لاَ نَبَاتَ بِهَا.\nصَفصَفًامُستَوِيَةً.\nوَلاَ أَمتًاارتِفَاعًا.\nوَعَنَتِخَضَعَت، وَذَلَّت.\nهَضمًانَقصًا مِن حَسَنَاتِهِ.\ndeeds\nاقرأ قصة من قصص الأمم السابقة، تجد فيها العبرة والعظة.\nاقرأ سورة من سور القرآن الكريم متأملًا موضوعها العام.\nقل: اللهم إني أسألك شفاعة نبيك محمد -صلى الله عليه وسلم- يوم القيامة.\nguid\nأقبل على القرآن الكريم تعلمًا، وتعليمًا، وعملًا؛ ففيه النجاة.\nتذكر يوم سكون الأصوات بين يدي الله تعالى، حتى لا يسمع إلا الهمس من عِظَم ما هم فيه من الهول.\nتذكر أن الشفاعة عند الله لا تنفع إلا بإذن الله للشافع، ورضاه عن المشفوع له.\nrefl\nكَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا ٩٩\nما يقص من أخبار الأمم ليس المقصود به قطع حصة الزمان، ولا إيناس السامعين بالحديث، إنَّما المقصود منه العبرة، والتذكرة، وإيقاظ لبصائر المشركين من العرب إلى موضع الاعتبار من هذه القصة. ابن عاشور:١٦/٣٠٢.\nما المقصود من قصص الأمم في القرآن الكريم؟\nوَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا ٩٩\nوهو هذا القرآن الكريم؛ ذكر للأخبار السابقة واللاحقة، وذكر يتذكر به ما لله تعالى من الأسماء والصفات الكاملة، ويتذكر به أحكام الأمر والنهي، وأحكام الجزاء. السعدي:٥١٢.\nلماذا سمي القرآن ذكرًا؟\nيَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا ١٠٣ نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا ١٠٤\nأي: يقول بعضهم لبعض في السرّ: إن لبثتم في الدنيا إلا عشر ليال؛ وذلك لاستقلالهم مدّة الدنيا. وقيل: يعنون لبثهم في القبور. ﴿يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمًا﴾ أي: يقول أعلمهم بالأمور؛ فالإضافة إليهم. ﴿إِن لَّبِثۡتُمۡ إِلَّا يَوۡمًا﴾: واحدًا؛ فاستقل المدّة أشدَّ مما استقلها غيره. ابن جزي:٢/٢٤.\nكيف دلّت هذه الآية على حقارة الدنيا؟\nيَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا ١٠٣ نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا ١٠٤\nوالمقصود من هذا: الندم العظيم؛ كيف ضيعوا الأوقات القصيرة، وقطعوها ساهين لاهين، معرضين عما ينفعهم، مقبلين على ما يضرهم، فها قد حضر الجزاء، وحَقَّ الوعيد، فلم يبق إلا الندم، والدعاء بالويل والثبور. السعدي:٥١٣.\nما الذي يفيده الإنسان من هذا الإخبار عن المجرمين؟\nوَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا ١١١\nوكنى عن الناس بالوجوه؛ لأن آثار الذل إنَّما تتبين في الوجه. القرطبي:١٤/١٤٢.\nما السبب في التعبير بالوجوه في الآية؟\nوَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا يَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا ١١٢\nلأن العمل لا يقبل من غير إيمان. القرطبي:١٤/١٤٣.\nبيّن منزلة الإيمان في قبول الأعمال الصالحة.\nوَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا ١١٣\nوهذا وصف يفيد المدح؛ لأنّ اللغة العربية أبلغ اللّغات، وأحسنها فصاحة وانسجامًا. ابن عاشور:١٦/٣١٤.\nما الذي يفيده وصف القرآن بـكونه عربيًا؟"],[320,"§طه\nwords\nفَتَعَالَىفَتَنَزَّهَ، وَارتَفَعَ، وَتَقَدَّسَ عَن كُلِّ نَقصٍ.\nعَزمًاحِفظًا لِمَا أُمِرَ بِهِ.\nوَطَفِقَاأَخَذَا.\nيَخصِفَانِيُلصِقَانِ.\nاجتَبَاهُاصطَفَاهُ.\nضَنكًاضَيِّقَةً شَاقَّةً.\ndeeds\nأكثر من الدعاء بزيادة العلم.\nاستعذ بالله من الشيطان الرجيم، وعوّذ أهلك وأولادك منه.\nتذكر ذنبًا كبيرًا فعلته، وأكثر من الاستغفار والإلحاح في ذلك؛ لعله يكون سببًا في اجتباء ربك لك.\nguid\nمن مداخل ابليس على بني آدم: عدم القناعة بالرزق، والتشبث بطول البقاء.\nاحرص على معرفة سيرة من نصحك قبل أن تقبل نصيحته.\nالحياة مع القرآن سبب لسعادة الدنيا والآخرة، والإعراض عنه سبب لشقاوة الدنيا والآخرة.\nrefl\nفَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ\nوفي وصفه بالحق إيماء إلى أن مُلك غيره من الـمُتَسَمِّين بالملوك لا يخلو من نقص. ابن عاشور:١٦/٣١٥.\nبيّن باختصار ثلاثة فروق بين مُلك الله ومُلك ملوك الدنيا.\nوَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا ١١٤\nويؤخذ من هذه الآية الكريمة: الأدب في تلقي العلم، وأن المستمع للعلم ينبغي له أن يتأنَّى ويصبر حتى يفرغ المعلم من كلامه المتصل بعضه ببعض، فإذا فرغ منه سأل إن كان عنده سؤال، ولا يبادر بالسؤال وقطع كلام مُلقِي العلم؛ فإنه سبب للحرمان. السعدي:٥١٤.\nما الأدب الذي يستقيه طالب العلم من هذه الآية؟\nوَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا ١١٤\nلما كانت عجلته على تَلَقُّف الوحي ومبادرته إليه تدل على محبته التامة للعلم، وحرصه عليه؛ أمره الله تعالى أن يسأله زيادة العلم. السعدي: ٥١٤.\nفي الآية وسيلة مهمة للحصول على العلم النافع، فما هي؟\nوَقُل رَّبِّ زِدۡنِي عِلۡمٗا ١١٤\nكان ابن مسعود -رضي الله عنه- إذا قرأ هذه الآية قال: \"اللهم زدني علمًا وإيمانًا ويقينًا\". البغوي:٣/١٤٢.\nكيف نتدبر هذه الآية ونعمل بها؟\nإِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ ١١٨ وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ ١١٩\nوقد قُرن بين انتفاء الجوع واللباس في قوله: ﴿إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ﴾، وقرن بين انتفاء الظمأ وألم الجسم في قوله: (وأنك لا تظمأ فيها ولا تضحى) لمناسبة بين الجوع والعَرى في أن الجوع خلوّ باطن الجسم عما يقيه تألمه؛ وذلك هو الطعام، وأن العري خلوّ ظاهر الجسم عما يقيه تألمه؛ وهو لفح الحر، وقرص البرد. ولمناسبة بين الظمأ وبين حرارة الشمس في أن الأول ألم حرارة الباطن، والثاني ألم حرارة الظاهر. ابن عاشور:١٦/٣٢٢.\nلماذا قرن الجوع بالعري، والظمأ بالضحى في الآيات الكريمة؟\nفَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ ١٢٣\nقال ابن عباس -رضي الله عنهما-: \"ضمن الله تعالى لمن قرأ القرآن وعمل به ألا يضل في الدنيا، ولا يشقى في الآخرة\"، وتلا الآية. القرطبي، ١٤/١٥٦.\nهل يكفي حفظ القرآن للهداية في الدنيا، والنجاة في الآخرة ؟\nوَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا\nفلا طمأنينة له، ولا انشراح لصدره، بل صدره ضيق حرج لضلاله، وإن تنعم ظاهره، ولبس ما شاء، وأكل ما شاء، وسكن حيث شاء؛ فإن قلبه ما لم يخلص إلى اليقين والهدى فهو في قلق، وحيرة، وشك، فلا يزال في ريبة يتردد، فهذا من ضنك المعيشة. ابن كثير:٣/١٦٤.\nهل نعيم الظاهر دليل على سعادة الباطن؟ وضح ذلك من الآية."],[321,"§طه\nwords\nالقُرُونِالأُمَمِ المُكَذِّبَةِ.\nلَكَانَ لِزَامًالَكَانَ الهَلاَكُ عَاجِلًا لاَزِمًا.\nآنَاءِسَاعَاتِ.\nمُتَرَبِّصٌمُنتَظِرٌ.\nالسَّوِيِّالمُستَقِيمِ.\ndeeds\nاجعل لك وردًا لمراجعة ما حفظت من القرآن، ولا تنسه.\nقل أذكار الصباح قبل طلوع الشمس، وأذكار المساء قبل غروبها، ولا تنسَ أن تسبح الله في بقية ليلك ونهارك.\nمُرْ إخوانك وأهل بيتك بأداء الصلاة في وقتها.\nguid\nليقتد الداعية بصبر النبي محمد -صلى الله عليه وسلم- على أذى المدعوين.\nإذا أوذيت فاحرص على كثرة التسبيح؛ خاصة بعد الفجر وقبيل المغرب؛ فإنه سببٌ لراحة القلب.\nإذا رأيت من زاده الله في زينة الدنيا عليك فلا تمدن عينيك إليه، وتذكر ما زادك الله في الدين عليه.\nrefl\nقَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ ١٢٦\nالنسيان في هذه الآية بمعنى: الترك. ولا مدخل للذهول في هذا الموضع، و(تُنسى) بمعنى: تترك في العذاب. ابن عطية:٤/٦٩.\nما المراد بالنسيان في الآية؟\nوَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ ١٢٧\nلكونه لا ينقطع، بخلاف عذاب الدنيا فإنه منقطع، فالواجب الخوف والحذر من عذاب الآخرة. السعدي:٥١٦.\nالمسلم قد يواجه صعوبات ومتاعب في حياته، فكيف يفيد من هذه الآية في تهوين هذه المصاعب عليه؟\nفَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ ١٣٠\nوأمره بأن يقبل على مزاولة تزكية نفسه وتزكية أهله بالصلاة، والإعراض عما متع الله الكفّار برفاهية العيش، ووعده بأن العاقبة للمتقين. ابن عاشور:١٦/٣٣٧.\nينبغي للمؤمن عند انتشار أذى المشركين الإقبال على تزكية نفسه وتقويتها بالعبادات للصمود أمام أذاهم، بيّن ذلك من الآية.\nوَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ ١٣١\nوفي هذه الآية إشارة إلى أن العبد إذا رأى من نفسه طموحًا إلى زينة الدنيا، وإقبالًا عليها، أن يذكرها ما أمامها من رزق ربه، وأن يوازن بين هذا وهذا. السعدي:٥١٧.\nتَمُرُّ على المسلم لحظاتٌ يشتهي فيها أن يكون من المنعمين المترفين في هذه الحياة الدنيا، فكيف يتعامل مع هذه اللحظات؟\nوَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ\nوالأمر بالشيء أمرٌ بجميع ما لا يتم إلا به، فيكون أمرًا بتعليمهم ما يصلح الصلاة، ويفسدها، ويكملها... فإن العبد إذا أقام صلاته على الوجه المأمور به؛ كان لما سواها من دينه أحفظ وأقوم، وإذا ضيعها كان لما سواها أضيع. السعدي:٥١٧.\nكيف يكون أمر الأهل وغيرهم بالصلاة؟ ولماذا خصّت الصلاة بالأمر بها والاصطبار عليها دون سائر العبادات؟\nوَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ ١٣٢\n﴿لَا نَسۡـَٔلُكَ رِزۡقًاۖ﴾ أي: لا نسألك أن ترزق نفسك ولا أهلك؛ فتفرغ أنت وأهلك للصلاة، فنحن نرزقك. وكان بعض السلف إذا أصاب أهله خصاصة قال: \"قوموا فصلوا؛ بهذا أمركم الله\"، ويتلو هذه الآية. ابن جزي:٢/٢٩.\nتضمنت هذه الآية منفعة عظيمة وثمرة من ثمار الصلاة، فما هي؟\nوَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ ١٣٢\nأي: لا نسألك أن ترزق نفسك وإياهم، وتشتغل عن الصلاة بسبب الرزق، بل نحن نتكفل برزقك وإياهم، فكان -عليه الصلاة والسلام- إذا نزل بأهله ضيق أمرهم بالصلاة. القرطبي:١٤/١٦٥.\nهل الانشغال بطلب الرزق عذر لتأخير الصلاة؟ وماذا تقول لمن ينشغل بعمله وقت الصلاة؟"],[322,"§الأنبياء\nwords\nمُحدَثٍحَدِيثِ التَّنزِيلِ يُجَدِّدُ الذِّكرَى لَهُم.\nوَأَسَرُّوا النَّجوَىبَالَغُوا فِي إِخفَاءِ مَا يَتَنَاجَونَ بِهِ.\nأَضغَاثُ أَحلاَمٍأَخلاَطُ مَنَامَاتٍ لاَ حَقِيقَةَ لَهَا.\nجَسَدًاأَجسَادًا خَارِجَةً عَن طِبَاعِ البَشَرِ.\nفِيهِ ذِكرُكُمفِيهِ عِزُّكُم، وَشَرَفُكُم، إِنِ اتَّعَظتُم بِهِ.\ndeeds\nاحرص على أذكار الصباح قبل طلوع الشمس، وعلى أذكار المساء قبل مغيب الشمس؛ حتى لا تكون لاهيًا.\nسَل عالمًا عن مسألة تجهلها.\nتدبر آية من الآيات التي تقرأها في وردك هذا اليوم.\nguid\nاقترب حسابك؛ فهل تشعر بهذا.\nطالب الحق يطلب الدليل لينقاد له لا لتعجيز خصمه.\nعليك بطلب العلم؛ فإن لطالب العلم منزلة رفيعة في الدنيا والآخرة.\nrefl\nٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ ١\nومن علم اقتراب الساعة قصر أمله، وطابت نفسه بالتوبة، ولم يركن إلى الدنيا، فكأن ما كان لم يكن إذا ذهب، وكل آت قريب، والموت لا محالة آت، وموت كل إنسان قيام ساعته، والقيامة أيضًا قريبة بالإضافة إلى ما مضى من الزمان، فما بقي من الدنيا أقل مما مضى. القرطبي:١٤/١٧١.\nلماذا يذكرنا الله تعالى باقتراب الساعة؟ وما أثر ذلك على المؤمن؟\nلَاهِيَةٗ قُلُوبُهُمۡۗ\n﴿لَاهِيَةً قُلُوبُهُمۡۗ﴾: غافلة؛ يقول: ما يستمع هؤلاء القوم الذين وصف صفتهم هذا القرآن إلا وهم يلعبون، غافلة عنه قلوبهم، لا يتدبرون حكمه، ولا يتفكرون فيما أودعه الله من الحجج عليهم. الطبري:١٨/٤١٠.\nبماذا يوصف من لا يتدبر القرآن الكريم؟\nفَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ٧\nلم يؤمر بسؤالهم إلا لأنه يجب عليهم التعليم، والإجابة عما علموه. السعدي:٥١٩.\nما حقوق المجتمع على العلماء، وطلبة العلم؟\nفَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ٧\nوفي تخصيص السؤال بأهل الذكر والعلم نهيٌ عن سؤال المعروف بالجهل وعدم العلم، ونهيٌ له أن يتصدى لذلك. السعدي:٥١٩.\nلا تقوم الحجة إلا بسؤال من له صفة معينة، فما هي؟\nفَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ٧\nلم يختلف العلماء أن العامة عليها تقليد علمائها، وأنهم المراد بقول الله تعالى: (فاسألوا). القرطبي:١٤/١٧٩.\nما الواجب على من لا علم عنده؟\nلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ ١٠\n(ذكركم) أي: شرفكم، وفخركم، وارتفاعكم؛ إن تذكرتم به ما فيه من الأخبار الصادقة فاعتقدتموها، وامتثلتم ما فيه من الأوامر، واجتنبتم ما فيه من النواهي ارتفع قدركم، وعظم أمركم. السعدي:٥١٩.\nمتى يصبح هذا الكتاب سببًا لشرفنا، وعزتنا، ورفعتنا؟\nلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ ١٠\nوتنكير (كتابًا) للتعظيم؛ إيماء إلى أنه جمع خصلتين عظيمتين: كونه كتاب هدى، وكونه آية ومعجزة للرسول لا يستطيع أحد أن يأتي بمثله، أو مُدَانِيه. ابن عاشور:١٧/٢٢.\nما فائدة تنكير (كتابًا) في الآية الكريمة؟"],[323,"§الأنبياء\nwords\nأَحَسُّوارَأَوا.\nحَصِيدًاكَالزَّرعِ المَحصُودِ.\nخَامِدِينَمَيِّتِينَ.\nفَيَدمَغُهُيَمحَقُهُ، وَيَدحَضُهُ.\nوَلاَ يَستَحسِرُونَلاَ يَمَلُّونَ.\nلاَ يَفتُرُونَلاَ يَضعُفُونَ، وَلاَ يَسأَمُونَ.\ndeeds\nسَلِ الله أن يجعل مسكنك وجميع ما رزقك عونًا لك على طاعته.\nحدد اليوم أحد العباد الصالحين وحاول أن تقتدي به في بعض عبادته.\nقل عشر مرات في الصباح ومثلها في المساء: \"لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير\".\nguid\nالتنديد بالظلم؛ وأعلى درجاته الشرك بالله.\nتذكر إهلاك الله تعالى للأمم والدول السابقة والحاضرة.\nلا توجد شبهة دينية إلا ولها ما يردها ويبطلها في القرآن أو السنة؛ فعليك بالعلم الشرعي.\nrefl\nبَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ\nوهذا عام في جميع المسائل الدينية؛ لا يورد مبطل شبهة عقلية ولا نقلية في إحقاق باطل أو رد حق، إلا في أدلة الله من القواطع العقلية والنقلية ما يُذهِبُ ذلك القول الباطل ويقمعه، فإذا هو متبين بطلانه لكل أحد. السعدي:٥٢٠.\nما أحسن طريق لإبطال شُبَهِ المشركين وأصحاب العقول الفاسدة؟\nوَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ ١٨\n﴿وَلَكُمُ ٱلۡوَيۡلُ﴾ يا معشر الكفار ﴿مِمَّا تَصِفُونَ﴾ الله بما لا يليق به من الصاحبة والولد. البغوي:٣/١٥٤.\nنرى في هذه الأزمنة المتأخرة من يصف الله تعالى، أو نبيه -صلى الله عليه وسلم-، أو الدين بالعظائم؛ فما جزاؤه من خلال تدبرك للآيات؟\nوَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ ١٩\n﴿وَمَنۡ عِندَهُۥ﴾ أي: من الملائكة، ﴿لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ﴾ أي: لا يملون، ولا يسأمونها؛ لشدة رغبتهم، وكمال محبتهم، وقوة أبدانهم. السعدي:٥٢٠-٥٢١\nمتى يكون العبد من ربه أقرب؟\nأَمِ ٱتَّخَذُوٓاْ ءَالِهَةٗ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ ٢١\nووصف الآلهة بأنها من الأرض تهكم بالمشركين، وإظهار لأَفَنِ رأيهم، أي: جعلوا لأنفسهم آلهة من عالَم الأرض، أو مأخوذة من أجزاء الأرض من حجارة أو خشب؛ تعريضًا بأن ما كان مثلَ ذلك لا يستحق أن يكون معبودًا. ابن عاشور:١٧/٣٧.\nكيف أفادت الآية الكريمة التهكم بالمشركين؟\nلَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ٢٢\nفاقتضى الكلام أمرين: أحدهما نفي كثرة الآلهة، ووجوب أن يكون الإله واحدًا، والأمر الثاني: أن يكون ذلك الواحد هو الله دون غيره. ابن جزي:٢/٣٤.\nدلت هذه الآية على أمرين في إثبات الألوهية لله وحده، بيّنهما.\nلَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ ٢٣\nلا يسأله الخلق عن قضائه في خلقه، وهو يسأل الخلق عن عملهم؛ لأنهم عبيد. القرطبي:١٤/١٨٩.\nفي الآية دليل على وجوب التسليم للشرع، وضح ذلك.\nبَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ ٢٤\nوليس عدم علمهم الحق لخفائه وغموضه، وإنَّما ذلك لإعراضهم عنه، وإلا فلو التفتوا إليه أدنى التفات تبين لهم الحق من الباطل تبينًا واضحًا جليًا. السعدي:٥٢١.\nما سبب ضلالة كثير من الناس؟"],[324,"§الأنبياء\nwords\nرَتقًامُلتَصِقَتَينِ.\nفَفَتَقنَاهُمَافَفَصَلنَاهُمَا بِقُدرَتِنَا.\nرَوَاسِيَجِبَالًا تُثَبِّتُهَا.\nأَن تَمِيدَلِئَلاَّ تَضطَرِبَ.\nفِجَاجًا سُبُلًاطُرُقًا وَاسِعَةً مَسلُوكَةً.\nمَحفُوظًالاَ تَسقُطُ، وَلاَ تَختَرِقُهَا الشَّيَاطِينُ.\nفِي فَلَكٍ يَسبَحُونَفِي مَدَارٍ يَجرِي فِيهِ لاَ يَحِيدُ عَنهُ.\ndeeds\nبادر بكتابة وصيتك هذا اليوم.\nادع الله أن يرزقك خشيته في الغيب والشهادة.\nتصور لو أن الماء انقطع عن مدينتك أسبوعًا فماذا سيحدث للناس؟! ثم احمد الله على نعمة الماء.\nguid\nاتبع منهج الأنبياء -عليهم السلام- ببدء دعوتك بتعريف الناس بالله تعالى وتحبيبهم له سبحانه.\nالمؤمن يتبع أوامر غيره إذا كانت غير مخالفة لأوامر الله سبحانه.\nالمؤمن لا ينفك عن الفتنة في هذه الدنيا؛ إما بالخير والنعمة ليرى الله تعالى شكره، وإما بالشر والمحنة ليرى الله تعالى صبره.\nrefl\nوَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ ٢٦\nولما كان اتخاذ الولد نقصًا في جانب واجب الوجود أعقب مقالتهم بكلمة (سبحانه) تنزيهًا له عن ذلك؛ فإن اتخاذ الولد إنَّما ينشأ عن الافتقار إلى إكمال النقص العارض بفقد الولد. ابن عاشور:١٧/٥٠.\nما الحكمة في ذكر التسبيح بعد مقالتهم؟\nلَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ\nأي: لا يقولون قولًا مما يتعلق بتدبير المملكة حتى يقول الله؛ لكمال أدبهم، وعلمهم بكمال حكمته وعلمه. السعدي:٥٢٢.\nلماذا كان من صفة الملائكة أنهم لا يسبقون الله تعالى بالقول؟\nوَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ ٢٩\nوأي ظلم أعظم من ادعاء المخلوق -الناقص الفقير إلى الله من جميع الوجوه- مشاركة الله في خصائص الإلهية والربوبية؟! السعدي:٥٢٢.\nما وجه وصف مدعي الألوهية بالظلم؟\nوَمَا جَعَلۡنَا لِبَشَرٖ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ ٣٤\nسببها أن الكفار طعنوا على النبي بأنه بشر يموت، وقيل: إنهم تمنوا موته ليشمتوا به، وهذا أنسب لما بعده. ابن جزي:٢/٣٦.\nكيف رد القرآن على من تنقص النبي بكونه سيموت؟\nكُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ\nوهذه الآية تدل على بطلان قول من قال ببقاء الخضر، وأنه مُخَلَّد في الدنيا؛ فهو قول لا دليل عليه، ومناقض للأدلة الشرعية. السعدي:٥٢٣.\nيقول البعض: إن الخضر خالدٌ مخلد في الدنيا، فما رأيك؟\nكُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ ٣٥\n﴿وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ﴾ أي: نختبركم بالفقر والغنى، والصحة والمرض، وغير ذلك من أحوال الدنيا؛ ليظهر الصبر على الشر، والشكر على الخير، أو خلاف ذلك. ابن جزي:٢/٣٦.\nما الحكمة من تنوع الابتلاء بالشر والخير؟\nوَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ ٣٥\nقال ابن زيد: \"نبلوهم بما يحبون وبما يكرهون، نختبرهم بذلك؛ لننظر كيف شكرهم فيما يحبون، وكيف صبرهم فيما يكرهون\". الطبري:١٨/٤٤٠.\nكيف يكون الابتلاء بالخير والشر؟"],[325,"§الأنبياء\nwords\nفَتَبهَتُهُمفَتُحَيِّرُهُم.\nفَحَاقَفَحَلَّ، وَأَحَاطَ.\nيَكلَؤُكُميَحفَظُكُم، وَيَحرُسُكُم.\nيُصحَبُونَيُجَارُونَ، وَيُمنَعُونَ.\ndeeds\nاستمع درسًا لأحد العلماء؛ فإن من نقصان الأرض موت العلماء، فكن لهم خليفة بعد موتهم.\nألق كلمة، أو أرسل رسالة؛ تبين فيها لمن تمسك بدينه أن العاقبة لهم والخسارة لمن استهزأ بهم.\nصلِّ الفجر في جماعة، ثم احرص على أذكار الصباح والمساء طلبًا للحفظ من الله تعالى.\nguid\nالأصل في الإنسان العجلة؛ فمن استسلم لها خسر، ومن غيَّر طبعه بالتربية إلى الحلم والرفق والأناة ربح وصار قدوة لغيره.\nمتاع الدنيا وزينتها سببٌ لضلال كثيرٍ من الناس.\nالتأمل في أحوال الأمم المهلَكة سببٌ للابتعاد عن الذنوب والمعاصي، والإقبال على الله سبحانه.\nrefl\nوَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ كَٰفِرُونَ ٣٦ خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٖۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ ٣٧\nوالحكمة في ذكر العجلة هاهنا: أنه لمَّا ذكر المستهزئين بالرسول -صلوات الله وسلامه عليه- وقع في النفوس سرعة الانتقام منهم، واستعجلت ذلك، فقال الله تعالى: ﴿خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٍۚ﴾؛ لأنه تعالى يملي للظالم، حتى إذا أخذه لم يفلته. ابن كثير:٣/١٧٥.\nما الحكمة من ذكر العجلة بعد ذكر المستهزئين برسول الله -صلى الله عليه وسلم-؟\nخُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٖۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ ٣٧\nواعلم أنه لا إشكال في قوله تعالى: ﴿خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٍۚ﴾ مع قوله ﴿فَلَا تَسۡتَعۡجِلُونِ﴾ فلا يقال: كيف يقول: إن الإنسان خُلق من العجل وجُبل عليه، ثم ينهاه عما خُلق منه وجُبل عليه؟! لأنه تكليف بمحال؛ لأنا نقول: نعم هو جبل على العجل، ولكن في استطاعته أن يُلزم نفسه بالتأني، كما أنه جبل على حب الشهوات مع أنه في استطاعته أن يلزم نفسه بالكف عنها. الشنقيطي:٤/١٥٢.\nكيف توجه كون العجلة من طبيعة الإنسان، ثم ينهى عما خلق منه وجبل عليه؟\nلَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ ٣٩\nوذكر الوجوه خاصة؛ لشرفها من الإنسان، وأنها موضع حواسه، وهو أحرص على الدفاع عنه، ثم ذكر الظهور؛ ليبين عموم النار لجميع أبدانهم. ابن عطية:٤/٨٣\nما وجه تخصيص ذكر الوجوه والظهور في الآية؟\nقُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ ٤٢\n﴿قُلۡ مَن يَكۡلَؤُكُم﴾ أي: يحرسكم ويحفظكم.. وتقديره: قل لا حافظ لكم (بالليل) إذا نمتم، وبالنهار إذا قمتم وتصرفتم في أموركم. القرطبي:١٤/٢٠٧-٢٠٨.\nهل استشعرت يومًا حراسة الله تعالى لك بالليل والنهار؟\nقُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ ٤٢\nوقدم الليل؛ لأنه زمن المخاوف؛ لأن الظلام يُعين أسباب الضر على الوصول إلى مبتغاها؛ من إنسان، وحيوان، وعلل الأجسام. ابن عاشور:١٧/٧٤.\nلماذا قدم الليل على النهار في الآية الكريمة؟\nبَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ\nأي: بسطنا لهم، ولآبائهم في نعيمها، وطال عليهم العمر في النعمة، فظنوا أنها لا تزول عنهم، فاغتروا، وأعرضوا عن تدبر حجج الله -عز وجل-. القرطبي:١٤/٢٠٩.\nمتى يقع العبد في الاغترار بنعمة الله تعالى عليه ؟\nبَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ ٤٤\n﴿بَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ﴾ أي: متعناهم بالنعم والعافية في الدنيا، فطغوا بذلك، ونسوا عقاب الله. ابن جزي:٢/٣٧.\nمتى يكون النعيم والثراء وبالًا على العبد؟"],[326,"§الأنبياء\nwords\nأُنذِرُكُمأُخَوِّفُكُم.\nنَفحَةٌنَصِيبٌ يَسِيرٌ.\nمِثقَالَ حَبَّةٍما يُعَادِل وَزنَ ذَرَّةٍ.\nفَطَرَهُنَّخَلَقَهُنَّ.\nلأَكِيدَنلَأَمكُرَنَّ، وَأُكَسِّرَنَّ.\nمُدبِرِينَذَاهِبِينَ.\ndeeds\nذكر أحد زملائك أو أقاربك بآية قرآنية، أو حديث نبوي.\nتذكر اليوم من ظلمته في مال، أو عرض، أو حق؛ فتحلل منه قبل ألا تستطيع.\nتأمل في قصة إبراهيم، واستخرج أسلوبين ناجحين من أساليب الحوار أو النهي عن المنكر.\nguid\nالمبالغة في حب الشيء يورث الصمم، حتى لا يرى إلا ما أحبه.\nالقوي في الحجة والإقناع هو الذي يستخدم أدلة الوحي من قرآن وسنة في دعوته وموعظته.\nالآلام والمصاعب التي تواجهك في الدنيا تذكرة لك؛ تُذَكِّرُك بعذاب الله، ودافعٌ يدفعك إلى التوبة والاستغفار.\nrefl\nقُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ ٤٥\nعن قتادة يقول: \"إن الكافر قد صم عن كتاب الله؛ لا يسمعه، ولا ينتفع به، ولا يعقله، كما يسمعه المؤمن وأهل الإيمان\". الطبري: ١٨/٤٥٠.\nما الفرق بين المؤمن والكافر تجاه كتاب الله تعالى؟\nوَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ ٤٥\nأي: الأصم لا يسمع صوتًا؛ لأن سمعه قد فسد وتعطل، وشرط السماع مع الصوت: أن يوجد محل قابل لذلك؛ كذلك الوحي سبب لحياة القلوب والأرواح، وللفقه عن الله؛ ولكن إذا كان القلب غير قابل لسماع الهدى كان بالنسبة للهدى والإيمان بمنزلة الأصم بالنسبة إلى الأصوات. السعدي:٥٢٤.\nما وجه تشبيه الكفار بالصُمِّ؟ وكيف يُؤَهِّلُ الإنسان نفسه للإفادة من كتاب الله -عز وجل-؟\nوَلَئِن مَّسَّتۡهُمۡ نَفۡحَةٞ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ ٤٦\nفالمعنى: ولئن مسهم أقل شيء من العذاب (ليقولن يا ويلنا إنا كنا ظالمين) أي: متعدين؛ فيعترفون حين لا ينفعهم الاعتراف. القرطبي:١٤/٢١١.\nكيف يكون حال الإنسان إذا نزل به أقل شيء من عذاب الله تعالى؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ ٤٨\nوخص المتقين بالذكر؛ لأنهم المنتفعون بذلك علمًا وعملًا. السعدي:٥٢٥.\nلماذا خَصَّ الله المتقين بالذكر؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ ٤٨ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ\nأي: يخشونه في حال غيبتهم، وعدم مشاهدة الناس لهم، فمع المشاهدة أولى؛ فيتورعون عما حرم، ويقومون بما ألزم. السعدي:٥٢٥.\nما الحكمة من تقييد الخشية بالغيب؟\nوَهَٰذَا ذِكۡرٞ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ ٥٠\nووصف القرآن بالمبارك يعمّ نواحي الخير كلها؛ لأن البركة زيادة الخير، فالقرآن كلّه خير: من جهة بلاغة ألفاظه، وحسنها، وسرعة حفظه، وسهولة تلاوته، وهو أيضًا خير لما اشتمل عليه من أفنان الكلام، والحكمة، والشريعة، واللطائف البلاغية... وبذلك اهتدت به أمم كثيرة في جميع الأزمان، وانتفع به مَن آمنوا به. ابن عاشور:١٧/٩٠.\nاذكر أنواعًا من بركة القرآن الكريم.\nوَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ ٥٧\nأخبر أنه لم يكتف بالمحاجة باللسان، بل كَسَر أصنامهم؛ فعل واثق بالله تعالى، موطِّن نفسه على مقاساة المكروه في الذب عن الدين. القرطبي:١٤/٢١٦-٢١٧.\nبيِّن إلى أي حد بلغت ثقة إبراهيم -عليه السلام- بربه -جل وعلا-."],[327,"§الأنبياء\nwords\nجُذَاذًاقِطَعًا صَغِيرَةً.\nعَلَى أَعيُنِ النَّاسِبِمَرًاى مِنَ النَّاسِ.\nنُكِسُوا عَلَى رُؤُوسِهِمرَجَعُوا إِلَى عِنَادِهِم.\nأُفٍّ لَكُمقُبحًا لَكُم.\nنَافِلَةًزِيَادَةً عَمَّا سَأَلَ.\ndeeds\nاقرأ كتابًا في أساليب الحوار والإقناع، وإقامة الحجج، وتعلّم ذلك من خلال النظر في حوارات الكتاب والسنة.\nسل الله تعالى أن يرزقك ذرية صالحة.\nتقرب إلى الله تعالى بطاعة من الطاعات؛ ينجك الله بها وقت الشدة.\nguid\nإدانة الخصم من لسانه من أعلى أنواع الإدانات.\nالهداية ليست بمجرد العقل أو لمكانة الإنسان، بل هي منة من الله سبحانه.\nالعناد يحرم صاحبه خيري الدنيا والآخرة.\nrefl\nفَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ\nوتأمل هذا الاحتراز العجيب: فإنَّ كل ممقوت عند الله لا يطلق عليه ألفاظ التعظيم إلا على وجه إضافته لأصحابه؛ كما كان النبي -صلى الله عليه وسلم- إذا كتب إلى ملوك الأرض المشركين يقول: «إلى عظيم الفرس...»، «إلى عظيم الروم...»، ونحو ذلك، ولم يقل: \"إلى العظيم\". وهنا قال تعالى: ﴿إِلَّا كَبِيرًا لَّهُمۡ﴾، ولم يقل: \"كبيرًا من أصنامهم\"؛ فهذا ينبغي التنبه له والاحتراز من تعظيم ما حقره الله، إلا إذا أضيف إلى من عَظَّمَه. السعدي:٥٢٦.\nلماذا عبر سبحانه في وصف الصنم بقوله: ﴿كَبِيرًا لَّهُمۡ﴾؟\nفَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ ٦٣\nوإنَّما أراد بهذا أن يبادروا من تلقاء أنفسهم، فيعترفوا أنهم لا ينطقون، وأن هذا لا يصدر عن هذا الصنم؛ لأنه جماد. ابن كثير:٣/١٧٨.\nما القصد الذي أراده إبراهيم من هذا السؤال؟\nثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ ٦٥\n(ثم نكسوا على رؤوسهم): استعارة لانقلابهم برجوعهم عن الاعتراف بالحق إلى الباطل والمعاندة، فقالوا: ﴿لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ﴾ أي: فكيف تأمرنا بسؤالهم؟ فهم قد اعترفوا بأنهم لا ينطقون، وهم مع ذلك يعبدونهم؛ فهذه غاية الضلال في فعلهم، وغاية المكابرة والمعاندة في جدالهم. ابن جزي:٢/٣٩.\nما عادة أهل الباطل إذا ظهر لهم الحق؟\nقَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ ٦٨\nلمَّا دحضت حجتهم، وبان عجزهم، وظهر الحق، واندفع الباطل؛ عدلوا إلى استعمال جاه ملكهم، فقالوا: ﴿حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ﴾. ابن كثير:٣/١٧٩.\nما الطريقة التي يلجأ إليها العاجزون عن إيجاد دليل لمَّا يقولون؟\nقُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ ٦٩\nوعن أبي العالية: \"لو لم يقل الله: (وسلامًا) لكان بردها أشد عليه من حرها، ولو لم يقل: ﴿عَلَىٰٓ إِبۡرَٰهِيمَ﴾ لكان بردها باقيًا إلى الأبد\". الشنقيطي:٤/١٦٣.\nلماذا جاء الأمر بأن تكون النار سلامًا؟ ولماذا خصها بإبراهيم -عليه السلام-؟\nوَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ ٧١\nهي الشام؛ خرج إليها من العراق. وبركتها بخصبها، وكثرة الأنبياء فيها. ابن جزي:٢/٤٠.\nما نوع البركة في أرض الشام؟\nوَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ ٧٢\n﴿وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةًۖ﴾ أي: زيادة؛ لأنه دعا في إسحق، وزِيد يعقوب من غير دعاء؛ فكان ذلك نافلة؛ أي: زيادة على ما سأل؛ إذ قال: ﴿رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ﴾. ويقال لولد الولد: نافلة لأنه زيادة على الولد. القرطبي:١٤/٢٣٠.\nيقول العلماء: إن العبد إذا صدق مع الله أعطاه فوق ما يرجو، وزاده فوق ما يأمل، دلل على ذلك من الآية."],[328,"§الأنبياء\nwords\nقَومَ سَوءٍأَهلَ فَسَادٍ وَقُبحٍ.\nنَفَشَتانتَشَرَت فِيهِ لَيلًا بِلاَ رَاعٍ.\nصَنعَةَ لَبُوسٍصِنَاعَةَ الدُّرُوعِ يَعمَلُهَا حِلَقًا مُتَشَابِكَةً.\nلِتُحصِنَكُملِتَحمِيَكُم.\nبَأسِكُمحَربِكُم.\nعَاصِفَةً شَدِيدَةَ الهُبُوبِ.\ndeeds\nخفف عن مصاب مصيبته، أو تصدّق من مالك في سبيل الله، أو صم صيام نافلة تطوعًا لله.\nقل: \"اللهم يا معلم إبراهيم علمني ويا مفهم سليمان فهمني\".\nشارك في دورة مهارية تتعلم فيها صنعة نافعة.\nguid\nفضل الدعوة إلى الله تعالى وشرف القائمين بها.\nالخبث إذا كثر في الأمة استوجب الهلاك والدمار.\nعند الكرب الجأ إلى الله تعالى؛ فلا فرج إلا من عنده.\nrefl\nوَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا\nوهذا من أكبر نعم الله على عبده: أن يكون إمامًا يهتدي به المهتدون، ويمشي خلفه السالكون. السعدي:٥٢٧.\nما الذي يفاد من امتنان الله على إبراهيم وذريته بجعلهم أئمة؟ وما النعمة التي يستشعرها حافظ القرآن وطالب العلم إذا قرأ هذه الآية؟\nوَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ\n﴿وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ﴾: وهذا شامل لجميع الخيرات من حقوق الله وحقوق العباد، (وإقام الصلاة وإيتاء الزكاة) هذا من باب عطف الخاص على العام؛ لشرف هاتين العبادتين وفضلهما، ولأن من كمَّلهما كما أُمِرَ كان قائمًا بدينه، ومن ضَيَّعهما كان لما سواهما أضيع، ولأن الصلاة أفضل الأعمال التي فيها حقه تعالى، والزكاة أفضل الأعمال التي فيها الإحسان لخلقه. السعدي:٥٢٧.\nلماذا خص الصلاة والزكاة بالذكر مع أنهما داخلان في عموم الخيرات؟\nوَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ ٧٨ فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ\n﴿فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ﴾ أي: فهمناه هذه القضية، ولا يدل ذلك أن داود لم يفهمه الله في غيرها، ولهذا خصها بالذكر؛ بدليل قوله: (وَكُلًّا) من داود وسليمان ﴿ءَاتَيۡنَا حُكۡمًا وَعِلۡمًاۚ﴾؛ وهذا دليل على أن الحاكم قد يصيب الحق والصواب وقد يخطئ ذلك، وليس بملوم إذا أخطأ مع بذل اجتهاده. السعدي: ٥٢٨.\nمتى يُعذر الحاكم، أو القاضي، أو المعلم، أو الوالد في خطئه؟\nوَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ ٧٨ فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ\nقال الحسن: \"لولا هذه الآية؛ لرأيت القضاة هلكوا، ولكنه تعالى أثنى على سليمان بصوابه، وعذر داود باجتهاده\". القرطبي:١٤/٢٣٧.\nبيّن رحمة الله تعالى بأهل العلم والقضاء في هذه الآية.\nوَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ\nوذلك أنه كان من أعبد الناس، وأكثرهم لله ذكرًا وتسبيحًا وتمجيدًا. السعدي:٥٢٨.\nلماذا خَصَّ الله داود بهذه الخاصية، وهي أن الجبال والطير تسبح معه؟\nوَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ ٧٩\nوالظاهر أن قوله: ﴿وَكُنَّا فَٰعِلِينَ﴾ مؤكد لقوله: (وَسَخرنا مَعَ دَاوودَ الجِبالَ يُسَبِّحنَ وَالطّيرَ). والموجب لهذا التأكيد أن تسخير الجبال وتسبيحها أمر عجب خارق للعادة، مظنة لأن يُكذِّب به الكفرة الجهلة. الشنقيطي:٤/٢٣٢.\nما المناسبة في ختم الآية بجملة: ﴿وَكُنَّا فَٰعِلِينَ﴾؟\nوَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ ٨٠\nشكر العبد لربه: هو أن يستعين بنعمه على طاعته، وشكر الرب لعبده: هو أن يثيبه الثواب الجزيل من عمله القليل. الشنقيطي:٤/٢٣٤.\nمتى يوصف العبد بالشاكر؟ وكيف يشكر الربُّ تعالى عبده؟"],[329,"§الأنبياء\nwords\nيَغُوصُونَ لَهُيَغُوصُونَ فِي البِحَارِ؛ لاِستِخرَاجِ الَّلآلِئِ.\nنَقدِرَ عَلَيهِأَن لَّن نُضَيِّقَ عَلَيهِ فِي بَطنِ الحُوتِ، وَنُؤَاخِذَهُ.\nخَيرُ الوَارِثِينَخَيرُ البَاقِينَ، وَخَيرُ مَن خَلَفَنِي بِخَيرٍ.\nرَغَبًا وَرَهَبًارَجَاءً فِي الثَّوَابِ، وَخَوفًا مِنَ العِقَابِ.\ndeeds\nأَلقِ قصة من قصص القرآن عن سير الأنبياء على إخوتك أو أبنائك، مبينًا لهم أهم الفوائد، والعبر منها.\nتذكر ذنبًا فعلته وقعت بعده مصيبة، ثم قل: \"لا إله إلا أنت سبحانك؛ إني كنت من الظالمين\".\nبادر إلى الصلوات الخمس بعد النداء مباشرة.\nguid\nإذا أصابك شيءٌ من الضر فلا تتردد في رفع يديك إلى الله داعيًا.\nإذا اشتدت عليك المشاق والمصائب فارجع إلى قصة أيوب أو يوسف أو محمد -عليهم الصلاة والسلام- ففيها السلوى.\nعلو مقام الصبر، ومثله الشكر؛ فالأول على البأساء، والثاني على النعماء.\nrefl\nوَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ ٨٣ فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ ٨٤\n﴿وَذِكۡرَىٰ لِلۡعَٰبِدِينَ﴾ أي: وجعلناه في ذلك قدوة؛ لئلَّا يظن أهل البلاء أنما فعلنا بهم ذلك لهوانهم علينا، وليتأسوا به في الصبر على مقدورات الله وابتلائه لعباده بما يشاء. ابن كثير:٣/١٨٥.\nما وجه كون أيوب وقصته ذكرى للعابدين؟\nرَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ ٨٤\nابتليناه ليعظم ثوابه غدًا، ﴿وَذِكۡرَىٰ لِلۡعَٰبِدِينَ﴾ أي: وتذكيرًا للعباد؛ لأنهم إذا ذكروا بلاء أيوب، وصبره عليه، ومحنته له -وهو أفضل أهل زمانه-؛ وطَّنوا أنفسهم على الصبر على شدائد الدنيا، نحو ما فعل أيوب؛ فيكون هذا تنبيها لهم على إدامة العبادة، واحتمال الضرر. القرطبي:١٤/٢٦٣.\nبيّن الحكمة التي لأجلها ذكر الله تعالى ابتلاءه لأيوب -عليه السلام-.\nوَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ ٨٦\nوصفهم أيضًا بالصلاح؛ وهو يشمل: صلاح القلوب؛ بمعرفة الله، ومحبته، والإنابة إليه كل وقت. وصلاح اللسان؛ بأن يكون رطبًا من ذكر الله. وصلاح الجوارح؛ باشتغالها بطاعة الله، وكَفِّها عن المعاصي. السعدي:٥٢٩.\nمتى يوصف الإنسان بالصلاح؟\nوَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ ٨٧\n﴿فَنَادَىٰ فِي ٱلظُّلُمَٰتِ﴾: وهي ظلمة الليل، والبحر، وبطن الحوت. ابن جزي:٢/٤٣.\nما الظلمات التي كان فيها يونس -عليه السلام-؟ ثم بين باختصار أثر الذكر في كشف الكربة من خلال هذه الآية.\nلَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ ٨٧\nأقر لله تعالى بكمال الألوهية: ﴿لَّآ إِلَٰهَ إِلَّآ أَنتَ﴾، ونزهه عن كل نقص وعيب وآفة: (سبحانك)، واعترف بظلم نفسه وجنايته: ﴿إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ﴾. السعدي:٥٢٩.\nتضمن هذا الدعاء ثلاثة أمور استحق بها يونس أن ينجوَ بها من بطن الحوت؛ فما هذه الأمور الثلاثة؟\nوَكَذَٰلِكَ نُۨجِي ٱلۡمُؤۡمِنِينَ ٨٨\nأي: إذا كانوا في الشدائد، ودعونا منيبين إلينا، ولا سيما إذا دعوا بهذا الدعاء في حال البلاء. ابن كثير:٣/١٨٧.\nاذكر طريقةً مثلى للنجاة من الشدائد دلَّت عليها هذه الآية.\nفَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ\n﴿وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ﴾: بعدما كانت عاقرًا؛ لا يصلح رحمها للولادة؛ فأصلح الله رحمها للحمل لأجل نبيه زكريا. وهذا من فوائد الجليس والقرين الصالح؛ أنه مبارك على قرينه، فصار يحيى مشتركًا بين الوالدين. السعدي:٥٣٠.\nمستدلًا بهذه الآية، كيف يصبح القرين الصالح بركة على قرينه ومصاحبه؟"],[330,"§الأنبياء\nwords\nوَتَقَطَّعُوا أَمرَهُماختَلَفُوا عَلَى رُسُلِهِم، وَتَفَرَّقُوا.\nفَلاَ كُفرَانَ لِسَعيِهِفَلاَ جُحُودَ لِعَمَلِهِ.\nحَدَبٍمُرتَفِعٍ مِنَ الأَرضِ.\nيَنسِلُونَيُسرِعُونَ.\nشَاخِصَةٌمَفتُوحَةٌ لاَ تَكَادُ تَطرِفُ.\nحَصَبُ جَهَنَّمَوَقُودُهَا، وَحَطَبُهَا.\ndeeds\nتعوذ بالله من فتنة يأجوج ومأجوج.\nزُرِ المقبرة؛ حتى لا تكون في غفلة عن آخرتك.\nسل الله تعالى أن تكون ممن سبقت لهم من الله تعالى الحسنى، وأن تكون من المبعدين عن جهنم.\nguid\nفضيلة العفة، والحياء وإحصان الفرج.\nالتوحيد الخالص عمدة وأساس لتوحيد الأمة الإسلامية.\nالإيمان شرط لقبول الصالحات.\nrefl\nوَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ ٩١\nهكذا يذكر تعالى قصة مريم وابنها عيسى -عليهما السلام- مقرونة بقصة زكريا وابنه يحيى -عليهما السلام- فيذكر أولًا قصة زكريا، ثم يتبعها قصة مريم؛ لأن تلك مربوطة بهذه؛ فإنها إيجاد ولد من شيخ كبير قد طعن في السن، ومن امرأة عجوز عاقر لم تكن تلد في حال شبابها، ثم يذكر قصة مريم وهي أعجب؛ فإنها إيجاد ولد من أنثى بلا ذكر، هكذا وقع في سورة آل عمران، وفي سورة مريم، وهاهنا. ابن كثير:٣/١٨٩.\nكثيرًا ما يقترن ذكر قصة مريم وعيسى بقصة يحيى وزكريا -عليهم السلام-، فلماذا؟\nإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ ٩٢\nأي: هؤلاء الرسل المذكورون هم أمتكم، وأئمتكم الذين بهم تأتمون، وبهديهم تقتدون؛ كلهم على دين واحد، وصراط واحد، والرب أيضًا واحد، ولهذا قال: ﴿وَإِنَّ رَبَّكُمُ﴾. السعدي:٥٣٠.\nكيف تكون جميع الرسل وأتباعها أمةً واحدة؟\nإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ ٩٢ وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ ٩٣\nأي: هذه أمتكم ما دامت أمة واحدة، واجتمعتم على التوحيد؛ فإذا تفرقتم وخالفتم فليس من خالف الحق من جملة أهل الدين الحق. القرطبي:١٤/٢٨٣.\nبيّن منزلة الاجتماع على الحق وترك الافتراق.\nإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ ٩٢\nومعنى كونها واحدة: أنها توحّد الله تعالى؛ فليس دونه إله، وهذا حال شرائع التوحيد، وبخلافها أديان الشرك؛ فإنها لتعدد آلهتها تتشعب إلى عدة أديان؛ لأن لكل صنم عبادةً وأتباعًا، وإن كان يجمعها وصف الشرك. ابن عاشور:١٧/١٤١.\nالتوحيد يوحد الأمة، والشرك يفرقها؛ بيّن ذلك.\nوَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ\nففي ذلك اليوم ترى أبصار الكفار شاخصة من شدة الأفزاع، والأهوال المزعجة، والقلاقل المفظعة، وما كانوا يعرفون من جناياتهم وذنوبهم، وأنهم يدعون بالويل والثبور، والندم والحسرة على ما فات. السعدي:٥٣١.\nما سبب شخوص أبصار الذين كفروا يوم القيامة؟\nإِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ ٩٨\nوإنَّما يخرج من هذا من عُبد مع كراهته لأن يُعبد ويطاع في معصية الله؛ فهم الذين سبقت لهم الحسنى؛ كالمسيح، والعزير، وغيرهما؛ فأولئك (مبعدون). ابن تيمية:٤/٣٩٣.\nالمسيح -عليه السلام- والحسين -رضي الله عنه- والجيلاني -رحمه الله- عُبدوا من دون الله؛ فهل يدخلون في الآية؟ ولماذا ؟\nإِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ ٩٨\nوالحكمة في دخول الأصنام النار -وهي جماد لا تعقل، وليس عليها ذنب- بيان كذب من اتخذها آلهة، وليزداد عذابهم. السعدي:٥٣١.\nما الحكمة في دخول الأصنام النار؟"],[331,"§الأنبياء\nwords\nحَسِيسَهَاصَوتَ لَهِيبِهَا، وَاحتِرَاقِ الأَجسَادِ فِيهَا.\nالفَزَعُ الأَكبَرالهَولُ الأَعظَمُ يَومَ القِيَامَةِ.\nكَطَيِّ السِّجِلِّ لِلكُتُبكَمَا تُطوَى الصَّحِيفَةُ عَلَى مَا كُتِبَ فِيهَا.\nالزَّبُورِالكُتُبِ المُنَزَّلَةِ عَلَى الأَنبِيَاءِ.\nالذِّكراللَّوحِ المَحفُوظِ.\nآذَنتُكُمأَعلَمتُكُم مَا أُمِرتُ بِهِ.\nعَلَى سَوَاءٍأَنَا وَأَنتُم مُستَوُونَ فِي العِلمِ بِهِ.\ndeeds\nادع الله تعالى أن يمكن لعباده الصالحين في الأرض.\nنشر رسالة تبيّن فيها مظاهر رحمة النبي -صلى الله عليه وسلم- بالخلق.\nاطلب الاستعانة بالله على كل عمل تعمله.\nguid\nالعبادة والصلاح سبب لوراثة الأرض.\nتمسك بهذا القرآن، واحفظه، وتعلم معانيه؛ فإن فيه بلاغًا شافيًا كافيًا لمن تمسك به.\nالتزامك بأنواع العبادات هو سبب التوفيق لفهم القرآن الكريم، والعمل به.\nrefl\nلَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ\nوالفزع الأكبر: أهوال يوم القيامة والبعث... وقال الحسن: \"هو وقت يؤمر بالعباد إلى النار\"، وقال ابن جريج وسعيد بن جبير والضحاك: \"هو إذا أطبقت النار على أهلها، وذبح الموت بين الجنة والنار\". القرطبي:١٤/٢٩٥.\nلماذا لا يحزن المؤمنون في الآخرة من الفزع الأكبر؟\nيَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ ١٠٤\nروى مسلم عن ابن عباس، قال: قام فينا رسول الله بموعظة؛ فقال: «يا أيها الناس إنكم تُحشرون إلى الله حُفاة عراة غُرلًا: ﴿كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٍ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ﴾». ابن عاشور:١٧/١٦١.\nمن خلال الآية الكريمة وضح كيف كان -صلى الله عليه وسلم- يعظ الناس بالقرآن الكريم.\nوَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ ١٠٥\nالأرض هنا على الإطلاق في مشارق الأرض ومغاربها، وقيل: الأرض المقدسة، وقيل: أرض الجنة، والأول أظهر. والعباد الصالحون: أمّة محمد -صلى الله عليه وسلم-؛ ففي الآية ثناء عليهم، وإخبار بظهور غيب مصداقه في الوجود؛ إذ فتح الله لهذه الأمة مشارق الأرض ومغاربها. ابن جزي:٢/٤٦.\nما صفة الذين وعدهم الله بوراثة الأرض؟\nوَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ ١٠٥\nقال ابن عباس -رضي الله عنهما-: \"أراد أن أراضي الكفار يفتحها المسلمون\"، وهذا حكم من الله بإظهار الدين، وإعزاز المسلمين. البغوي:٣/١٩٦.\nفي الآية بشرى للصالحين، فما هي؟\nوَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ ١٠٧\nوالمعنى على كل وجه: أن الله رحم العالمين بإرسال سيدنا محمد -صلى الله عليه وسلم-؛ لأنه جاءهم بالسعادة الكبرى، والنجاة من الشقاوة العظمى، ونالوا على يديه الخيرات الكثيرة في الآخرة والأولى، وعلمهم بعد الجهالة، وهداهم بعد الضلالة. ابن جزي:٢/٤٦.\nكيف كان النبي -صلى الله عليه وسلم- هو الرحمة المهداة؟\nوَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ ١٠٧\nإن قيل: رحمة للعالمين عموم، والكفار لم يُرحموا به؟ فالجواب من وجهين؛ أحدهما: أنهم كانوا معرَّضين للرحمة به لو آمنوا؛ فهم الذين تركوا الرحمة بعد تعريضها لهم. والآخر: أنهم رُحموا به؛ لكونهم لم يُعاقبوا بمثل ما عوقب به الكفار المتقدّمون؛ من الطوفان، والصيحة، وشبه ذلك. ابن جزي:٢/٤٦.\nما الجواب على من قال: ﴿رَحۡمَةً لِّلۡعَٰلَمِينَ﴾ عموم، والكفار لم يرحموا به؟\nوَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ ١٠٧\nعن ابن عباس في قوله: ﴿وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةً لِّلۡعَٰلَمِينَ﴾ قال: تمت الرحمة لمن آمن به في الدنيا والآخرة، ومن لم يؤمن به عوفي مما أصاب الأمم قبل. الطبري:١٨/٥٥٢.\nكيف صار نبينا محمد -صلى الله عليه وسلم- رحمة للمؤمن به والكافر؟"],[332,"§الحج\nwords\nتَذهَلُتَغفُلُ، وَتَنشَغِلُ.\nمَرِيدٍمُتَمَرِّدٍ.\nعَلَقَةٍدَمٍ أَحمَرَ غَلِيظٍ تَعَلَّقَ فِي الرَّحِمِ.\nمُضغَةٍقِطعَةِ لَحمٍ صَغِيرَةٍ قَدرَ مَا يُمضَغُ.\nمُخَلَّقَةٍتَامَّةِ الخَلقِ.\ndeeds\nسَلِ الله تعالى الأمن يوم الفزع، ثم قل: \"اللهم إني أسألك الهدى، والتقى، والعفاف، والغنى\".\nألق كلمة، أو أرسل رسالةً تبين فيها خطر الجدال في الدين بغير علم.\nاستعذ بالله من أن ترد إلى أرذل العمر.\nguid\nتقرير عقيدة البعث والجزاء بذكر أحوالهما وأهوالهما.\nحرمة الكلام في شرع الله بغير علم من وحي إلهي، أو كلام نبوي صحيح.\nموالاة الشياطين وأتباعهم تُفْضي إلى الضلالة ودخول جهنم وعذاب السعير.\nrefl\nيَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ\nيخاطب الله الناس كافة بأن يتقوا ربهم؛ الذي رباهم بالنعم الظاهرة والباطنة، فحقيق بهم أن يتقوه، بترك الشرك والفسوق والعصيان، ويمتثلوا أوامره مهما استطاعوا. السعدي:٥٣٢.\nلماذا خُصَّ ذكر الرب هنا دون سائر أسماء الله وصفاته؟\nيَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمٞ ١ يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ ٢\nفائدة ذكر هول ذلك اليوم: التحريض على التأهب له، والاستعداد بالعمل الصالح. القرطبي: ١٤/٣١١.\nما فائد ذكر أهوال القيامة؟\nيَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ\nمع أنها مجبولة على شدة محبتها لولدها، خصوصًا في هذه الحال التي لا يعيش إلا بها. السعدي:٥٣٣.\nلماذا خُصَّت المرضعة بالذكر هنا؟\nيَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ\nإنَّما لم يقل مرضع؛ لأن المرضعة هي التي في حال الإرضاع ملقمة ثديها للصبي، والمرضع التي شأنها أن ترضع وإن لم تباشر الإرضاع في حال وصفها به، فقال: (مرضعة) ليكون ذلك أعظم في الذهول؛ إذ تنزع ثديها من فم الصبي حينئذ. ابن جزي:٢/ ٤٨.\nما الوجه البلاغي في الوصف بــِ (مرضعة) دون «مرضع»؟\nوَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ ٢\nتشبيه بالسكارى من شدّة الغمّ. ابن جزي:٢/٤٩.\nلم شبههم بالسكارى مع كونهم ليسوا كذلك؟\nوَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ ٣\nقال الفخر الرازي في تفسيره: \"هذه الآية بمفهومها تدل على جواز المجادلة الحقة؛ لأن تخصيص المجادلة مع عدم العلم بالدلائل يدل على أن المجادلة مع العلم جائزة، فالمجادلة الباطلة هي المراد من قوله: ﴿مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢا﴾ [الزخرف: ٥٨]، والمجادلة الحقة هي المراد من قوله: ﴿وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُ﴾ [النحل: ١٢٥]\" اهـ منه. الشنقيطي:٤/٢٦٣.\nالجدال نوعان فما هما؟ وما الجائز منهما؟\nوَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ ٣\nهذه حال الضال المتبع لمن يضله، فلم يحتج إلى تفصيل، فبيّن أنه يجادل بغير علم، ويتبع كل شيطان مريد؛ كتب على ذلك الشيطان أنه من تولاه فأنه يضله ويهديه إلى عذاب السعير، وهذه حال مقلد أئمة الضلال بين أهل الكتاب وأهل البدع؛ فإنهم يجادلون في الله بغير علم، ويتبعون من شياطين الجن والإنس من يضلهم. ابن تيمية:٤/٤٠١.\nبيّن خطورة تقليد أئمة الضلال."],[333,"§الحج\nwords\nثَانِيَ عِطفِهِلاَوِيًا عُنُقَهُ فِي تَكَبُّرٍ.\nعَلَى حَرفٍعَلَى ضَعفٍ، وَشَكٍّ، وَتَرَدُّدٍ.\nخَيرٌصِحَّةٌ، وَسَعَةُ رِزقٍ.\nفِتنَةٌاِبتِلاَءٌ بِمَكرُوهٍ وَشِدَّةٍ.\nالمَولَىىالنَّاصِرُ.\nثُمَّ ليَقطَعأَي: لِيَقطَع ذَلِكَ الحَبلَ.\ndeeds\nاحضر دورة علمية، أو استمع إليها عن طريق التسجيل لتكون على هدى وعلم.\nقل: \"رب زدني علما\".\nقل: \"اللهم يا مقلب القلوب ثبت قلبي على دينك\".\nguid\nمن الجهل الجدال في الدين بغير علم.\nمن أشد الحرمان والعقوبات أن يزين لك حرب هذا الدين والاجتهاد في ذلك.\nاحذر من علامة المنافق: عبادة وقت الرخاء، وردة وقت الابتلاء.\nrefl\nوَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ ٨\nفليس عنده علم ضروري، ولا علم مكتسب بالنظر الصحيح العقلي، ولا علم من وحي؛ فهو جاهل محض من جميع الجهات. الشنقيطي:٤/٢٨٠.\nمتى يستطيع الإنسان الجدال، أو الحوار؟\nثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٞۖ\n﴿لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٌۖ﴾: وهو الإهانة والذل؛ كما أنه استكبر عن آيات الله لقاه الله المذلة في الدنيا، وعاقبه فيها قبل الآخرة؛ لأنها أكبر همه ومبلغ علمه. ابن كثير:٣/٢٠٣.\nلماذا كان جزاء ثاني العطف عند سماع القرآن أن يُذل؟ ولماذا كان ذله في الدنيا قبل الآخرة؟\nوَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ ١١\nنزلت في قوم من الأعراب: كان أحدهم إذا أسلم فاتفق له ما يعجبه في ماله وولده؛ قال: هذا دين حسن، وإن اتفق له خلاف ذلك؛ تشاءم به، وارتدّ عن الإسلام. ابن جزي:٢/٥٠.\nما رأيك فيمن يستقيم أو يدخل في الدين للحصول على المكاسب الدنيوية فقط؟\nخَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ\nأما في الدنيا؛ فإنه لا يحصل له بالردة ما أَمَّله الذي جعل الردة رأسًا لماله، وعوضًا عما يظن إدراكه، فخاب سعيه، ولم يحصل له إلا ما قسم له. السعدي:٥٣٥.\nما وجه خسارة المرتد للدنيا؟\nوَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ\nأي: ومن الناس من هو ضعيف الإيمان، لم يدخل الإيمان قلبه، ولم تخالطه بشاشته، بل دخل فيه: إما خوفًا، وإما عادة على وجه لا يثبت عند المحن. السعدي:٥٣٤.\nما السبب الذي يجعل إيمان المرء على حَرفٍ مُهَدَّدًا فيه بالزوال؟\nيَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ ١٢ يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ ١٣\n﴿يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ﴾: فيها إشكالان؛ الأول: في المعنى؛ وهو كونه وصف الأصنام بأنها لا تضر ولا تنفع، ثم وصفها بأن ضرّها أقرب من نفعها؛ فنفى الضرّ ثم أثبته. فالجواب: أن الضر المنفي أولًا يُراد به ما يكون من فعلها؛ وهي لا تفعل شيئًا، والضر الثاني: يراد به ما يكون بسببها من العذاب وغيره. ابن جزي:٢/٥١.\nكيف وصفت الأصنام بأنها لا تضر ولا تنفع، ثم وصفها بأن ضرها أقرب من نفعها ؟\nيَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ ١٣\nلأن شأن المولى جلب النفع لمولاه، وشأن العشير جلب الخير لعشيره؛ فإذا تخلف ذلك منهما نادرًا كان مذمة وغضاضة، فأما أن يكون ذلك منه مطردًا فذلك شر الموالي. ابن عاشور:١٧/٢١٦.\nما سبب كون الأصنام بئس المولى، وبئس العشير؟"],[334,"§الحج\nwords\nوَالصَّابِئِينَعَبَدَةَ المَلاَئِكَةِ، أَوِ الكَوَاكِبِ.\nوَالمَجُوسَعَبَدَةَ النَّارِ.\nالحَمِيمُالمَاءُ المُتَنَاهِي فِي حَرِّهِ.\nيُصهَرُ بِهِيُذَابُ بِهِ.\nمَقَامِعُمَطَارِقُ.\ndeeds\nاسجد سجود التلاوة عند قراءة هذه الآية مستشعرًا أنه ليس كل الناس يسجدون هذا السجود.\nأخبر من حولك بهذه الحقيقة التي قررها القرآن: أن من كتب الله عليه الهوان فلن يستطيع أحد أن يعزه، وأن من أراد العزة فليطلبها من الله سبحانه.\nاستعذ بالله من عذاب جهنم؛ فإن عذابها لا يطاق.\nguid\nتذكر أن الهداية بيد الله تعالى وحده؛ فلا تذهب نفسك حسرات على العصاة والمكذبين، وتأمل عظيم ما اختصك الله به من نعمة الهداية.\nتدبر القرآن طريق للهداية.\nتقرير إرادة الله ومشيئته المطلقة؛ فهو تعالى يفعل ما يشاء، ويهدي من يريد.\nrefl\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ\n﴿وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ﴾: إنَّما ذكر هذه على التنصيص؛ لأنها قد عُبدت من دون الله، فبين أنها تسجد لخالقها، وأنها مربوبة مسخرة. ابن كثير:٣/٢٠٥.\nلماذا خُصَّت هذه الآيات الكونية بالذكر دون غيرها؟\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ\nما من جماد إلا وهو مطيع لله خاشع له مسبح له كما أخبر الله تعالى عن السموات والأرض ﴿قَالَتَآ أَتَيۡنَا طَآئِعِينَ﴾ [فصلت: ١١]، وقال في وصف الحجارة: ﴿وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِ﴾ [البقرة: ٧٤]، وقال تعالى: ﴿وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡ﴾ [الإسراء: ٤٤]: البغوي٣/٢٠٦\nهل المخلوقات تعبد الله تعالى؟ وأي شيء نتعلمه من ذلك؟\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ\nيسجد لعظمته كل شيء طوعًا وكرهًا؛ وسجود كل شيء مما يختص به. ابن كثير:٣/٢٠٥.\nكيف تسجد المخلوقات لله -عز وجل-؟\nوَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩ ١٨\nيقول تعالى ذكره: ومن يهنه الله من خلقه فَيُشْقِهِ، ﴿فَمَا لَهُۥ مِن مُّكۡرِمٍۚ﴾ بالسعادة يسعده بها؛ لأن الأمور كلها بيد الله، يوفق من يشاء لطاعته، ويخذل من يشاء، ويُشقي من أراد، ويُسعد من أحب. وقوله: ﴿إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩﴾: يقول تعالى ذكره: إن الله يفعل في خلقه ما يشاء من إهانة من أراد إهانته، وإكرام من أراد كرامته؛ لأن الخلق خلقه، والأمر أمره. الطبري:١٨/٥٨٧.\nمن الذي يملك الإكرام والإهانة على وجه الحقيقة؟ ولماذا؟\nفَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ ١٩\nقال سعيد بن جبير: \"ثياب من نحاس مذاب، وليس من الآنية شيء إذا حمي أشد حرًّا منه، وسمي باسم الثياب لأنها تحيط بهم كإحاطة الثياب\"، وقال بعضهم: \"يلبس أهل النار مقطعات من النار\". البغوي: ٣/٢٠٩.\nكيف تكون النار لباسًا لأهل النار -والعياذ بالله تعالى-؟\nكُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ٢٢\nوقوله: ﴿وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ﴾ كقوله: ﴿وَقِيلَ لَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ﴾ [السجدة: ٢٠]. ومعنى الكلام: أنهم يهانون بالعذاب قولًا وفعلًا. ابن كثير ٥/٤٠٧.\nلماذا يُقال لأهل النار وهم يعذبون: ذوقوا عذاب الحريق؟\nوَلِبَاسُهُمۡ فِيهَا حَرِيرٞ ٢٣\n﴿وَلِبَاسُهُمۡ فِيهَا حَرِيرٌ﴾: في مقابلة ثياب أهل النار التي فصلت لهم. ابن كثير:٣/٢٠٧.\nما سبب الحديث عن لباس أهل الجنة؟"],[335,"§الحج\nwords\nالعَاكِفُ فِيهِالمُقِيمُ فِيهِ.\nوَالبَادِالقَادِمُ إِلَيهِ.\nبِإِلحَادٍ بِظُلمٍبِمَيلٍ عَنِ الحَقِّ ظُلمًا.\nبَوَّأنَاهَيَّأنَا، وَبَيَّنَّا.\nضَامِرٍالبَعِيرِ خَفِيفِ اللَّحمِ مِنَ الأَعمَالِ لاَ مِنَ الهُزَالِ.\ndeeds\nاجتهد هذا اليوم ألَّا تتكلم إلا بكلامٍ طيب.\nأكثر اليوم من قول: \"لا إله إلا الله\"؛ فهي الكلمة الطيبة التي من أكثر منها وعمل بها مات عليها.\nنظف يبتًا من بيوت الله، محتسبًا في ذلك الأجر من الله.\nguid\nعظِّم شأن الحرم، وحاذر أن تفكر فيه بالمعاصي؛ إذ يؤاخذ فيه على مجرد إرادة المعصية.\nالاشتغال بالصدِّ عن سبيل الله يستوجب العذاب الأليم.\nالمساجد أقيمت لعبادة الله وحده، لا لبنائها على القبور والأضرحة والشرك بالله.\nrefl\nإِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۢ بِظُلۡمٖ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمٖ ٢٥\n(الإلحاد): الميل عن الصواب، و(الظلم) هنا عام في المعاصي من الكفر إلى الصغائر؛ لأن الذنوب في مكة أشدّ منها في غيرها، وقيل: هو استحلال الحرام. ابن جزي:٢/٥٤.\nكيف دلّت هذه الآية على تعظيم الله لبيته الحرام؟\nوَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ ٢٦\nوتطهير البيت عام في الكفر، والبدع، وجميع الأنجاس، والدماء. القرطبي:١٤/٣٥٩.\nبيِّن كيف يكون تطهير البيت.\nوَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ ٢٧\nوقد حصل ما وعد الله به؛ أتاه الناس رجالًا وركبانًا من مشارق الأرض ومغاربها. السعدي:٥٣٧.\nفي الآية وجهٌ من وجوه إعجاز القرآن المتعلقة بالإخبار بالمغيبات، بيِّن ذلك.\nوَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ ٢٧\nومن حكمة مشروعيته تلقي عقيدة توحيد الله بطريق المشاهدة للهيكل الذي أقيم لذلك؛ حتى يرسخ معنى التوحيد في النفوس؛ لأن للنفوس ميلًا إلى المحسوسات؛ ليتقوى الإدراك العقلي بمشاهدة المحسوس. ابن عاشور:١٧/٢٤٣.\nاذكر حكمة من حكم مشروعية الحج.\nوَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ ٢٩\nقال قتادة: \"سمي عتيقًا لأن الله أعتقه من أيدي الجبابرة أن يصلوا إلى تخريبه، فلم يظهر عليه جبار قط\"، وقال سفيان بن عيينة: \"سمي عتيقًا لأنه لم يملك قط\". البغوي:٣/٢١٦.\nلم سمي المسجد الحرام بالبيت العتيق؟\nذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ\nأي: ومن يجتنب معاصيه ومحارمه، ويكون ارتكابها عظيمًا في نفسه ﴿فَهُوَ خَيۡرٌ لَّهُۥ عِندَ رَبِّهِۦۗ﴾؛ فكما على فعل الطاعات ثواب كثير وأجر جزيل؛ كذلك على ترك المحرمات، واجتناب المحظورات. ابن كثير:٣/٢١٢.\nكيف يمكن للمسلم أن يكسب الأجر الجزيل بدون أن يعمل شيئًا بجوارحه؟\nفَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ ٣٠\nووصف الأوثان بالرجس أنها رجس معنوي؛ لِكون اعتقاد إلهيتها في النفوس بمنزلة تعلّق الخبث بالأجساد. ابن عاشور:١٧/٢٥٣.\nلماذا وصفت الأوثان بالرجس في الآية الكريمة؟"],[336,"§الحج\nwords\nسَحِيقٍبَعِيدٍ مُهلِكٍ.\nمَحِلُّهَاوَقتُ ذَبحِهَا.\nمَنسَكًانُسُكًا وَعِبَادَةً؛ بِذَبحِ الأَنعَامِ تَقَرُّبًا لِلَّهِ.\nوَجِلَتخَافَت.\nصَوَآفَّقَائِمَاتٍ؛ قَد صُفَّت ثَلاَثٌ مِن قَوَائِمِهَا، وَقُيِّدَتِ الرَّابِعَةُ.\nوَجَبَتسَقَطَت عَلَى الأَرضِ بَعدَ النَّحرِ.\nالقَانِعَالفَقِيرَ الَّذِي لَم يَسأَل تَعَفُّفًا.\nوَالمُعتَرَّالَّذِي يَسأَلُ لِحَاجَتِهِ.\ndeeds\nحذّر الناس من الشرك بالله، وبيّن لهم خطورته.\nأقم الصلاة في جماعة.\nأطعم اليوم فقيرًا.\nguid\nعظِّم شعائر الله تعالى ظاهرًا وباطنًا، وإياك والاستخفاف بها.\nذكر الله من أعظم مقاصد العبادات؛ فعلى العبد أن يتذكر هذا المقصد العظيم دائمًا.\nلا تتسخط مما يحصل لك من المصائب، بل اصبر ابتغاء وجه ربك، واحتسب ثوابه، وارتقب أجره.\nrefl\nحُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ ٣١\nقيل: شبه حال المشرك بحال الهاوي من السماء في أنه لا يملك لنفسه حيلة حتى يقع؛ بحيث تسقطه الريح، فهو هالك لا محالة؛ إما باستلاب الطير لحمه، وإما بسقوطه إلى المكان السحيق، وقال الحسن: \"شبه أعمال الكفار بهذه الحال في أنها تذهب وتبطل؛ فلا يقدرون على شيء منها\". البغوي:٣/٢١٨.\nبيّن حال المشرك بالله تعالى في الدنيا والآخرة.\nذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ ٣٢\nوتعظيمها: إجلالها، وتوقيرها، والقصد إليها. وقيل: الشعائر أمور الدين على الإطلاق، وتعظيمها: القيام بها، وإجلالها. ابن جزي:٢/٥٦.\nكيف يعظم العبد شعائر الله؟\nذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ ٣٢\nفالمقصود تقوى القلوب لله؛ وهو: عبادتها له وحده دون ما سواه بغاية العبودية له، والعبودية فيها: غاية المحبة، وغاية الذل، والإخلاص؛ وهذه ملة إبراهيم الخليل، وهذا كله مما يبين أن عبادة القلوب هي الأصل. ابن تيمية:٤/٤٢٧.\nعبادة القلوب هي الأصل في العبادة، كيف دلت الآية على ذلك؟\nفَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ ٣٤ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣٥\nوقد أتبع صفة (المخبتين) بأربع صفات، وهي: وجل القلوب عند ذكر الله، والصّبر على الأذى في سبيله، وإقامة الصلاة، والإنفاق. ابن عاشور:١٧/٢٦١.\nيكون الإخبات لله بتحقيق أربع صفات، ما هي؟\nفَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ٣٦\nفالمعنى: أطعموا من سأل، ومن لم يسأل ممن تعرض بلسان حاله، وأطعموا من تعفف عن السؤال بالكلية، ومن تعرض للعطاء. ابن جزي:٢/٥٨.\nمن خلال الآية: بين باختصار كيف كان حرص الإسلام على التكافل الاجتماعي.\nكَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ٣٦\nمَنَّ سبحانه علينا بتذليلها، وتمكيننا من تصريفها، وهي أعظم منا أبدانًا وأقوى منا أعضاء؛ ذلك ليعلم العبد أن الأمور ليست على ما تظهر إلى العبد من التدبير، وإنَّما هي بحسب ما يريدها العزيز القدير، فيغلب الصغير الكبير؛ ليعلم الخلق أن الغالب هو الله الواحد القهار فوق عباده. القرطبي:١٤/٤٠٣.\nبيّن دقيق نعمة الله ومنته على عباده بتسخير هذه البهائم العظام.\nلَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ\nالمعنى لن تصلوا إلى رضا الله باللحوم ولا بالدماء، وإنَّما تصلون إليه بالتقوى؛ أي: بالإخلاص لله، وقصد وجه الله بما تذبحون وتنحرون من الهدايا؛ فعبر عن هذا المعنى بلفظ: ﴿لَن يَنَالَ﴾ مبالغة وتأكيدًا؛ لأنه قال: لن تصل لحومها، ولا دماؤها إلى الله، وإنَّما تصل بالتقوى منكم؛ فإن ذلك هو الذي طُلِب منكم، وعليه يحصل لكم الثواب. ابن جزي:٢/٥٨.\nما المقصد الأعظم من إقامة شعائر الحج؟"],[337,"§الحج\nwords\nصَوَامِعُمَعَابِدُ رُهبَانِ النَّصَارَى.\nوَبِيَعٌكَنَائِسُ النَّصَارَى.\nوَصَلَوَاتٌمَعَابِدُ اليَهُودِ.\nفَأَملَيتُفَأَمهَلتُ وَلَم أُعَاجِل بِالعُقُوبَةِ.\nخَاوِيَةٌ عَلَى عُرُوشِهَامُتَهَدِّمَةٌ، قَد سَقَطَت حِيطَانُهَا عَلَى سُقُوفِهَا.\nوَقَصرٍ مَشِيدٍمَرفُوعِ البُنيَانِ مُزَخرَفٍ قَد خَلاَ مِن سَاكِنِيهِ.\ndeeds\nادعُ لإخوانك المستضعفين من المسلمين في أرجاء المعمورة.\nحافظ على إقامة الصلاة، وحث من حولك عليها.\nأنكر بحكمة ما تراه من منكرات بين زملائك وفي حيك.\nguid\nوعد من الله سبحانه أن نصره يتنزل على من نصر دينه، ورفع شرعه.\nإن الله ليملي للظالمين حتى إذا أخذهم لم يفلتهم.\nالعبرة بالبصيرة القلبية لا بالبصر؛ فكم من أعمى هو أبصر للحقائق من ذي بصر.\nrefl\nٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ\nوهذا يدل على حكمة الجهاد، وأن المقصود منه إقامة دين الله، وذبُّ الكفار المؤذين للمؤمنين. السعدي:٥٣٩.\nأشارت الآية إلى حكمة من حكم مشروعية الجهاد، وضح ذلك\nوَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ\nالآية تقوية للإذن في القتال، وإظهار للمصلحة التي فيه؛ كأنه يقول: لولا القتال والجهاد لاستولى الكفار على المسلمين وذهب الدين. ابن جزي:٢/٥٩.\nفي الجهاد حكمة عظيمة في بقاء الدين، وضح ذلك.\nوَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ\nودل ذلك على أن البلدان التي حصلت فيها الطمأنينة بعبادة الله، وعمرت مساجدها، وأقيمت فيها شعائر الدين كلها من فضائل المجاهدين، وببركتهم دفع الله عنها الكافرين. السعدي:٥٣٩.\nللمجاهدين أفضال على المسلمين، بيِّن ذلك.\nوَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ\nومعاني هذه الأسماء هي في الأمم التي لها كتاب على قديم الدهر، ولم يذكر في هذه المجوس، ولا أهل الإشراك؛ لأن هؤلاء ليس لهم ما تجب حمايته، ولا يوجد ذكر الله إلا عند أهل الشرائع. ابن عطية:٤/١٢٥.\nما وجه عدم ذكر معابد المجوس والمشركين في الآية؟\nوَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ\nأي: من ينصر دينه وأولياءه، وهو وعد تضمن الحض على القتال. ابن جزي:٢/٥٩.\nما شرط تحقيق النصر؟\nٱلَّذِينَ إِن مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ٤١\nفمن قام بهذه الأمور نصره الله على عدوه. ابن تيمية: ٤/٤٣٤.\nما واجب المجاهدين عند تمكينهم في الأرض؟\nفَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ ٤٦\nمعناه: أن العمى الضار هو عمى القلب، فأما عمى البصر فليس بضار في أمر الدين. البغوي:١٤/٢٢٤.\nما العمى الضار الذي يوجب هلاك الإنسان؟"],[338,"§الحج\nwords\nأَملَيتُ لَهَاأَمهَلتُهَا، وَلَم أُعَاجِلهَا بِالعُقُوبَةِ.\nتَمَنَّىقَرَأَ الآيَاتِ المُنزَلَةَ عَلَيهِم.\nفَتُخبِتَتَخضَعَ، وَتَسكُنَ.\nمِريَةٍشَكٍّ.\nبَغتَةًفَجأَةً.\nيَومٍ عَقِيمٍلاَ خَيرَ فِيهِ، وَلاَ يَومَ بَعدَهُ، وَهُوَ يَومُ القِيَامَةِ.\ndeeds\nقل: \"اللهم إني أعوذ برضاك من سخطك، وبعفوك من عقوبتك، وبك منك؛ لا نحصى ثناء عليك، أنت كما أثنيت على نفسك\".\nتذكر خلال الأسبوع الماضي كم تركت من واجب شرعي، وكم وقع منك من معصية، ثم أكثر من الاستغفار حتى لا تتمادى في غفلتك وقسوة قلبك.\nحدد ثلاثة أسباب تحس أنها ترقق قلبك، ثم اعمل بها.\nguid\nكن داعيًا إلى الله تعـالى؛ محذرًا من عقوبته، مبينًا للنـاس دينهم.\nاحرص على تخليص قلبك من الشهوات والشبهات بالذكر وطلب العلم؛ فإن بقاءها فيه سببٌ للافتتان عن دين الله.\nأهمية العناية بأعمال القلوب؛ كالمحبة، والخشية، والتعظيم، وغيرها.\nrefl\nوَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ\nفلم يكن مبادرتهم بالظلم موجبًا لمبادرتنا بالعقوبة. السعدي:٥٤١.\nهل تنعم الظالم وأمنه واطمئنانه دليلٌ على صحة أفعاله؟\nفَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ٥٠\nووصفه بالكريم يجمع وفرته وصفاءَه من المكدرات. ابن عاشور:١٧/٢٩٤.\nعلى ماذا يدل وصف الرزق بالكريم في الآية الكريمة؟\nلِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۢ بَعِيدٖ ٥٣\nأي: محنة، وبلية، وشك، ونفاق. (وَالقاسِيَةِ) يعني: الجافية (قُلوبُهُم) عن قبول الحق؛ وهم المشركون؛ وذلك أنهم افتتنوا لمَّا سمعوا ذلك. البغوي:٣/٢٢٨.\nما القلوب التي تؤثر فيها وساوس الشيطان، وتفتنها؟\nلِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۢ بَعِيدٖ ٥٣ وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ\n﴿لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةً﴾ لطائفتين من الناس لا يبالي الله بهم؛ وهم: الذين ﴿فِي قُلُوبِهِم مَّرَضٌ﴾ أي: ضعف وعدم إيمان تام وتصديق جازم؛ فيؤثر في قلوبهم أدنى شبهة تطرأ عليها، فإذا سمعوا ما ألقاه الشيطان داخَلَهم الرَّيب والشك؛ فصار فتنة لهم. ﴿وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ﴾ أي: الغليظة، التي لا يؤثر فيها زجر ولا تذكير، ولا تفهم عن الله وعن رسوله لقسوتها... فما يلقيه الشيطان يكون فتنة لهؤلاء الطائفتين؛ فيظهر به ما في قلوبهم من الخبث الكامن فيها. وأمَّا الطائفة الثالثة فإنه يكون رحمة في حقها؛ وهم المذكورون بقوله: ﴿وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ﴾؛ لأن الله منحهم من العلم ما به يعرفون الحق من الباطل، والرشد من الغي؛ فيميزون بين الأمرين. السعدي:٥٤٢.\nينقسم الناس أمام الشبهات إلى ثلاثة أقسام، ما هي؟\nلِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۢ بَعِيدٖ ٥٣ وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٥٤\nجعل الله القلوب ثلاثة أقسام: قاسية، وذات مرض، ومؤمنة مخبتة. ابن تيمية:٤/٤٤١.\nما أقسام القلوب الواردة في الآيات الكريمة؟ وكيف تصنف قلبك؟\nوَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٥٤\nالحق كلما جودل أهله ظهرت حججه، وأسفرت وجوهه، ووضحت براهينه، وغمرت لججه؛ كما قال تعالى: ﴿يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗا﴾ [البقرة: ٢٦]. ﴿فَيُؤۡمِنُواْ بِهِۦ﴾ لما ظهر لهم من صحته بما ظهر من ضعف تلك الشبه، (فتخبت) أي: تطمئن وتخضع ﴿لَهُۥ قُلُوبُهُمۡۗ﴾ وتسكن به قلوبهم؛ فإن الله جعل فيها السكينة. البقاعي:١٣/٧٣.\nجدال أهل الحق مع غيرهم فيه خير للبشرية، بينه.\nوَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةٖ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ ٥٥\nيعني يوم بدر، ووصفه بالعقيم؛ لأنه لا ليلة لهم بعده، ولا يوم؛ لأنهم يقتلون فيه. ابن جزي:٢/٦٢.\nفي وصف اليوم بالعقيم تهديد وإنذار للكفار، وضح ذلك."],[339,"§الحج\nwords\nمُدخَلًاوَهُوَ الجَنَّةُ.\nبُغِيَ عَلَيهِاُعتُدِيَ عَلَيهِ.\nيُولِجُيُدخِلُ.\ndeeds\nاهجر رفقاء السوء، وأماكن المعصية؛ محتسبًا ذلك من أبواب الهجرة إلى الله سبحانه.\nتأمل بعد صلاة الفجر قدرة الله في دخول النهار في الليل.\nتعبّد لله بأسمائه الحسنى الواردة في هذا الوجه.\nguid\nثناء الله تعالى على من هاجر وترك أرضه وداره في سبيل الله دليل على خطورة الإقامة في دار الكفر.\nتذكر أن الله تعالى لا يخذل عبده إذا ظلم وأوذي في سبيله.\nكل دعوة تقام لجمع الكلمة وهي على غير منهج الله فهي باطلة.\nrefl\nفَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٥٧\n(مُّهِينٌ) لهم من شدته، وألمه، وبلوغه للأفئدة؛ كما استهانوا برسله وآياته أهانهم الله بالعذاب. السعدي:٥٤٣.\nكيف جازى الله المجرمين بجنس أعمالهم؟\nوَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ\nخص بالذكر منهم الذين هاجروا في سبيل الله ثم قتلوا أو ماتوا تنويهًا بشأن الهجرة. ابن عاشور:١٧/٣٠٩.\nلماذا خُصَّ المهاجرون في سبيل الله تعالى بالذكر مع أنهم داخلون في جملة المؤمنين الوارد ذكرهم في الآيات السابقة؟\nوَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ ٥٨\nيقول تعالى ذكره: والذين فارقوا أوطانهم وعشائرهم، فتركوا ذلك في رضا الله، وطاعته، وجهاد أعدائه، ثم قتلوا، أو ماتوا وهم كذلك؛ ليرزقنهم الله يوم القيامة في جناته رزقًا حسنًا؛ يعني بالحسن: الكريم. الطبري:١٨/٦٧٣.\nمتى يعتبر ترك الوطن عملًا صالحًا؟\nذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ ٦٠\n﴿إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ﴾: إن قيل: ما مناسبة هذين الوصفين للمعاقبة؟ فالجواب من وجهين؛ أحدهما: أن في ذكر هذين الوصفين إشعارًا بأن العفو أفضل من العقوبة؛ فكأنه حض على العفو. والثاني: أن في ذكرهما إعلامًا بعفو الله عن المعاقِب حين عاقب. ابن جزي:٢/٦٢.\nما مناسبة ختم الآية ب (العفو) و(الغفور)؟\nذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ ٦٠\nفالله هذا وصفه المستقر اللازم الذاتي، ومعاملته لعباده في جميع الأوقات بالعفو والمغفرة، فينبغي لكم أيها المظلومون المجني عليهم أن تعفوا وتصفحوا وتغفروا؛ ليعاملكم الله كما تعاملون عباده؛ ﴿فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِ﴾ [الشورى: ٤٠]. السعدي:٥٤٣.\nماذا تفيد من وصف الله -عز وجل- ب (العفو) و(الغفور)؟\nذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ ٦١\nفإن النصر يقتضي تغليب أحد الضدّين على ضدّه، وإقحام الجيش في الجيش الآخر في الملحمة؛ فضرب له مثلًا بتغليب مدة النهار على مدة الليل في بعض السنة، وتغليب مدة الليل على مدة النهار في بعضها. ابن عاشور:١٧/٣١٤.\nتتقلب أحوال الناس من غالب إلى مغلوب، كيف مثلت الآية الكريمة هذا المعنى؟\nوَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ٦٢\nومن كبريائه: أن العبادات كلها الصادرة من أهل السماوات والأرض؛ كلها المقصود منها تكبيره وتعظيمه وإجلاله وإكرامه؛ ولهذا كان التكبير شعارًا للعبادات الكبار؛ كالصلاة وغيرها. السعدي:٥٤٤.\nلماذا كان التكبير شعارًا للعبادات الكبار؟"],[340,"§الحج\nwords\nوَالفُلكَالسُّفُنَ.\nمَنسَكًاشَرِيعَةً، وَعِبَادَةً.\nفِي كِتَابٍ هُوَ اللَّوحُ المَحفُوظُ.\nسُلطَانًاحُجَّةً، وَبُرهَانًا.\nالمُنكَرَالكَرَاهَةَ ظَاهِرَةً عَلَى وُجُوهِهِم.\nيَسطُونَيَبطِشُونَ.\nالمَصِيرالمَكَانُ الَّذِي يَصِيرُونَ إِلَيهِ.\ndeeds\nادع الله تعالى باسميه: (الرؤوف)، و(الرحيم) لعله يرحمك، ويتجاوز عنك.\nقل بعد استيقاظك: \"الحمد لله الذي أحياني بعد ما أماتني، وإليه النشور\".\nادعُ غيرك إلى الله بأي نوعٍ من أنواع الدعوة تجيده.\nguid\nالاعتزاز بالدين سبب للثبات عليه والدعوة إليه.\nتأدب بآداب الحوار؛ فلطالب الحق طريقة يجاب بها، وللمتعنت طريقة يردّ بسببها.\nادعُ غيرك إلى الله بأي نوعٍ من أنواع الدعوة تجيده.\nrefl\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ\nوإنَّما خصّ هذا بالذكر؛ لأن ذلك الجري في البحر هو مظهر التسخير؛ إذ لولا الإلهام إلى صُنعها على الصفة المعلومة لكان حظها من البحر الغَرق. ابن عاشور:١٧/٣٢٢.\nلماذا خصّ جريان الفلك في البحر بالذكر في الآية الكريمة من بين أحوال الفلك؟\nوَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ ٦٥\nفيكون قوله: ﴿وَيُمۡسِكُ ٱلسَّمَآءَ﴾ امتنانًا على الناس بالسلامة مما يُفسد حياتهم، ويكون قوله: ﴿إِلَّا بِإِذۡنِهِۦۚ﴾ احتراسًا؛ جمعًا بين الامتنان والتخويف. ابن عاشور:١٧/٣٢٣.\nبيّن الجمع بين الرجاء والخوف في الآية الكريمة.\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ ٦٥\n(إن الله بالناس لرؤوف رحيم): أرحم بهم من والديهم، ومن أنفسهم؛ ولهذا يريد لهم الخير، ويريدون لها الشر والضر، ومن رحمته أن سخر لهم ما سخر من هذه الأشياء. السعدي:٥٤٥.\nما وجه ختم الآية بصفتي (الرؤوف) و(الرحيم)؟\nإِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ ٦٦\nأي: لجحود لما ظهر من الآيات الدالة على قدرته ووحدانيته. وقيل: إنَّما قال ذلك لأن الغالب على الإنسان كفر النعم؛ كما قال تعالى: ﴿وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ﴾ [سبأ: ١٣]. القرطبي:١٤/٤٤٢.\nبيِّن لم وصف الإنسان بكفر النعم.\nلِّكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ\nأي: لا ينازعك المكذبون لك، ويعترضون على بعض ما جئتهم به بعقولهم الفاسدة؛ مثل منازعتهم في حل الميتة بقياسهم الفاسد... وكقولهم: ﴿إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْ﴾ [البقرة:٢٧٥]، ونحو ذلك من اعتراضاتهم التي لا يلزم الجواب عن أعيانها وهم منكرون لأصل الرسالة... فصاحب هذا الاعتراض المنكر لرسالة الرسول إذا زعم أنه يجادل ليسترشد يقال له: الكلام معك في إثبات الرسالة وعدمها، وإلا فالاقتصار على هذه دليل أن مقصوده التعنت والتعجيز. السعدي:٥٤٥.\nفي الآية إرشاد لكيفية مواجهة الطاعنين في بعض الأحكام الشرعية، بيِّنها.\nوَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ ٦٨\nفي هذه الآية أدب حسن علمه الله عباده في الرد على من جادل تعنتًا ومراءً؛ ألا يجاب ولا يناظر، ويدفع بهذا القول الذي علمه الله لنبيه -صلى الله عليه وسلم-. القرطبي:١٤/٤٤٥.\nبيِّن أدب الحوار مع من يجادل تعنتًا وعنادًا.\nيَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ ٧٢\n(قل) أي: يا محمد -صلى الله عليه وسلم-لهؤلاء: ﴿أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ﴾ أي: النار وعذابها ونكالها أشد وأشق وأطم وأعظم مما تخوفون به أولياء الله المؤمنين في الدنيا، وعذاب الآخرة على صنيعكم هذا أعظم مما تنالون منهم. ابن كثير:٥/٣٩٦.\nفي الآية تسلية للمستضعفين من المؤمنين، وتهديد للظالمين، بيّنه."],[341,"§الحج\nwords\nالطَّالِبُالمَعبُودُ مِن دُونِ اللهِ الَّذِي أُخِذَ مِنهُ شَيءٌ.\nوَالمَطلُوبُ الذُّبَابُ.\nمَا قَدَرُوامَا عَظَّمُوا.\nيَصطَفِييَختَارُ.\nاجتَبَاكُماصطَفَاكُم.\nمِلَّةَ أَبِيكُمهَذِهِ المِلَّةَ السَّمحَةَ مِلَّةَ أَبِيكُم.\nمَولاَكُممَالِكُكُم وَنَاصِرُكُم، وَمُتَوَلِّي أُمُورِكُم.\ndeeds\nأطل اليوم الركوع والسجود، فإن الله سبحانه يحب ذلك.\nاحرص اليوم على أداء السنن الرواتب مع صلاتك للفرائض حيث أمر الله.\nساعد محتاجًا بمالٍ، أو جهد، أو قضاء حاجة.\nguid\nعظِّم الله سبحانه في قلبك بالمحبة والخشية تعظمه جوارحك.\nاعتصم بالله مولاك في كل وقت وحين؛ فإن من اعتصم بغيره هلك وخسر.\nاعلم أن العمل الصالح يحتاج إلى مجاهدة، وصبر، وبذل، ومشقة؛ فاصبر على ذلك.\nrefl\nمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ ٧٤\nوقوله: ﴿مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ﴾ يقول: ما عظم هؤلاء الذين جعلوا الآلهة لله شريكًا في العبادة حق عظمته حين أشركوا به غيره، فلم يخلصوا له العبادة، ولا عرفوه حق معرفته؛ من قولهم: ما عرفت لفلان قدره إذا خاطبوا بذلك من قصر بحقه، وهم يريدون تعظيمه. الطبري:١٨/٦٨٦.\nمن طاف على القبور، أو ذبح لها، أو صلى إليها ما قدر الله حق قدره، وضح ذلك من الآية.\nٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ ٧٥\nفاصطفى الله جبريل من الملائكة، واصطفى محمدًا -صلى الله عليه وسلم-من البشر. ابن تيمية:٤/٤٤٤.\nبيِّن فضل النبي -صلى الله عليه وسلم- من خلال الآية الكريمة.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩ ٧٧\nفعند استيفاء ما سيق إلى المشركين من الحجج والقوارع والنداء على مساوي أعمالهم خُتمت السورة بالإقبال على خطاب المؤمنين بما يُصلح أعمالهم، وينوّه بشأنهم. وفي هذا الترتيب إيماء إلى أن الاشتغال بإصلاح الاعتقاد مقدم على الاشتغال بإصلاح الأعمال. ابن عاشور:١٧/٣٤٥.\nإصلاح الاعتقاد مقدم على إصلاح العمل، بين هذا من الآيات الكريمة.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩ ٧٧\nالمراد بالركوع والسجود: الصلوات، وتخصيصهما بالذكر من بين أعمال الصلاة لأنهما أعظم أركان الصلاة؛ إذ بهما إظهار الخضوع والعبودية. ابن عاشور:١٧/٣٤٦.\nلماذا خصت الآية الكريمة الركوع والسجود من أفعال الصلاة؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩ ٧٧\n﴿وَٱعۡبُدُواْ رَبَّكُمۡ﴾: عموم في العبادة بعد ذكر الصلاة التي عبر عنها بالركوع والسجود، وإنَّما قدمها لأنها أهم العبادات. ابن جزي:٢/٦٥.\nما مناسبة تقديم ذكر الصلاة مع أنها من سائر العبادات؟\nوَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ\nالجهاد: بذل الوسع في حصول الغرض المطلوب، فالجهاد في الله حق جهاده هو: القيام التام بأمر الله، ودعوة الخلق إلى سبيله بكل طريق موصل إلى ذلك؛ من: نصيحة، وتعليم، وقتال، وأدب، وزجر، ووعظ، وغير ذلك. السعدي:٥٤٧.\nهل الجهاد مقتصر على استخدام السلاح في دفع الأعداء؟\nهُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ\nأخبر أنه ما جعل علينا في الدين من حرج نفيًا عامًّا مؤكَّدًا، فمن اعتقد أن فيما أمر الله به مثقال ذرة من حرج فقد كذَّب الله ورسوله، فكيف بمن اعتقد أن المأمور به قد يكون فسادًا وضررًا لا منفعة فيه ولا مصلحة لنا. ابن تيمية:٤/ ٤٤٨.\nليس فيما أمر الله تعالى به حرجٌ أو ضررٌ، بين ذلك من خلال الآية الكريمة."],[342,"§المؤمنون\nwords\nأَفلَحَفَازَ.\nاللَّغوِ مَا لاَ خَيرَ فِيهِ مِنَ الأَقوَالِ وَالأَفعَالِ.\nرَاعُونَحَافِظُونَ.\nنُطفَةًمَنِيَّ الرِّجَالِ يَخرُجُ مِن أَصلاَبِهِم.\nقَرَارٍ مَكِينِهُوَ الرَّحِمُ تَستَقِرُّ فِيهِ النُّطفَةُ.\nعَلَقَةًدَمًا أَحمَرَ مُلتَصِقًا بِالرَّحِمِ.\nمُضغَةًقِطعَةَ لَحمٍ قَدرَ مَا يُمضَغُ.\nسَبعَ طَرَائِقَسَمَاوَاتٍ بَعضُهَا فَوقَ بَعضٍ.\ndeeds\nحدد ثلاثة من أسباب الخشوع في الصلاة وطبقها اليوم في صلاتك.\nاجتهد اليوم في مجلسك في تغيير كلام اللغو إلى كلام مفيد.\nاجتهد في غض بصرك؛ فإنه سبب لحفظ الفرج.\nguid\nوعد الله من اتصف بهذه الصفات بفلاح، يشمل فلاح الدنيا والآخرة.\nالأمانة خلقٌ عظيم؛ فَرَاعِهَا.\nلتنال الفلاح حافظ على أداء الصلاة في أوقاتها.\nrefl\nقَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ ١ ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ ٢ إلى قوله تعالى ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ ١١\nأخبر -سبحانه وتعالى- أن هؤلاء هم الذين يرثون فردوس الجنة، وذلك يقتضي أنه لا يرثها غيرهم، وقد دل هذا على وجوب هذه الخصال؛ إذ لو كان فيها ما هو مستحب لكانت جنة الفردوس تورث بدونها؛ لأن الجنة تنال بفعل الواجبات دون المستحبات، ولهذا لم يذكر في هذه الخصال إلا ما هو واجب، وإذا كان الخشوع في الصلاة واجبًا؛ فالخشوع يتضمن السكينة والتواضع جميعًا. ابن تيمية:٤/٤٥٤.\nدلت الآية الكريمة على وجوب الخشوع، كيف ذلك؟\nٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ ٢\nوالخشوع في الصلاة... روح الصلاة، والمقصود منها، وهو الذي يكتب للعبد؛ فالصلاة التي لا خشوع فيها ولا حضور قلب، وإن كانت مجزئة مثابًا عليها، فإن الثواب على حسب ما يعقل القلب منها. السعدي:٥٤٧-٥٤٨.\nلماذا خص الخشوع بالذكر دون سائر أركان الصلاة وواجباتها؟\nوَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ ٣\nفي هذه الآية الكريمة: أن من صفات المؤمنين المفلحين إعراضهم عن اللغو، وأصل اللغو: ما لا فائدة فيه من الأقوال والأفعال؛ فيدخل فيه اللعب واللهو والهزل، وما توجب المروءة تركه. الشنقيطي:٥/٣٠٦.\nمن الفلاح تقليل الاشتغال ببرامج الهاتف الجوال والحاسب الآلي إذا كانت من اللغو، وضح ذلك من الآية.\nقَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ ١ ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ ٢ وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ ٣ وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ ٤ وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ ٥\nهذا تنويه من الله بذكر عباده المؤمنين، وذكر فلاحهم وسعادتهم، وبأي شيء وصلوا إلى ذلك، في ضمن ذلك: الحث على الاتصاف بصفاتهم، والترغيب فيها. فليَزِنِ العبدُ نفسه وغيره على هذه الآيات، ويعرف بذلك ما معه وما مع غيره من الإيمان زيادةً ونقصًا، كثرة وقلة. السعدي:٥٤٧.\nكيف يعرف الإنسان النقص الذي فيه؛ حتى يكمله؟\nوَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ ٨\nوالأمانة والعهد يجمع كل ما يحمله الإنسان من أمر دينه ودنياه، قولًا وفعلًا؛ وهذا يعم معاشرة الناس والمواعيد وغير ذلك، وغاية ذلك حفظه والقيام به. القرطبي:١٥/١٥.\nبيّن مفهوم الأمانات الواجب على العبد رعايتها.\nوَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ ٩\nالمحافظة عليها هي فعلها في أوقاتها؛ مع توفية شروطها، فإن قيل: كيف كرر ذكر الصلوات أولًا وآخرًا؟ فالجواب: أنه ليس بتكرار؛ لأنه قد ذكر أولًا الخشوع فيها، وذكر هنا المحافظة عليها؛ فهما مختلفان. ابن جزي:٢/٦٨.\nلم كرّر الله ذكر الصلاة في أول السورة، وفي هذا الموضع؟\nوَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ ١٧\nوقال أكثر المفسرين: أي: عن الخلق كلهم من أن تسقط عليهم، فتهلكهم. القرطبي:١٥/٢٢.\nبيّن صورة من صور حفظ الله تعالى للعبد."],[343,"§المؤمنون\nwords\nبِالدُّهنِبِالزَّيتِ.\nوَصِبغٍإِدَامٍ يُغمَسُ فِيهِ الخُبزُ.\nبِأَعيُنِنَابِحِفظِنَا وَكَلاَءَتِنَا؛ وَفِيهِ إِثبَاتُ صِفَةِ العَينِ لِلَّهِ عَلَى الوَجهِ اللاَّئِقِ بِهِ.\nوَفَارَ التَّنُّورُنَبَعَ المَاءُ مِنَ التَّنُّورِ المَعرُوفِ.\nفَاسلُك فِيهَافَأَدخِل فِيهَا.\nسَبَقَ عَلَيهِ القَولُاستَحَقَّ العَذَابَ.\ndeeds\nإذا شربت اليوم وغسلت فتذكر أن نعمة الماء العذب من أكثر نعم الله الدنيوية علينا؛ فأكثر من شكر الله عليها.\nاجعل في طعامك اليوم زيت الزيتون؛ فإنه من شجرة مباركة، وفيه من المنافع الشيء الكثير.\nقل عند ركوب الدابة: \"سبحان الذي سخّر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون\".\nguid\nأكثرمن العبادة الخالصة لله سبحانه.\nوجهاء المجتمع قادة مؤثرون في الخير أو في الشر؛ فلنحرص على صلاحهم.\nلا تتكل على نسبك؛ فالأنساب لا تنجي من عذاب الله تعالى.\nrefl\nوَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۢ بِهِۦ لَقَٰدِرُونَ ١٨\nيقول جل ثناؤه: وإنا على الماء الذي أسكناه في الأرض لقادرون أن نذهب به؛ فتهلكوا أيها الناس عطشًا، وتخرب أرضوكم، فلا تنبت زرعًا، ولا غرسًا، وتهلك مواشيكم. يقول: فمن نعمتي عليكم تركي ذلك لكم في الأرض جاريًا. الطبري:١٩/٢٠.\nما مصدر الماء الذي ينبع من الأرض؟\nوَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ\nأي: بحسب الحاجة؛ لا كثيرًا فيفسد الأرض والعمران، ولا قليلًا فلا يكفي الزروع والثمار، بل بقدر الحاجة إليه من السقي والشرب والانتفاع به. ابن كثير:٣/٢٣٥.\nما وجه الإنعام من إنزال الماء بقدر؟\nوَإِنَّا عَلَىٰ ذَهَابِۢ بِهِۦ لَقَٰدِرُونَ ١٨\nوهذا تنبيه منه لعباده أن يشكروه على نعمته، ويقدروا عدمها ماذا يحصل به من الضرر. السعدي:٥٤٩.\nفي الآية تنبيهٌ إلى طريقةٍ يعرف بها الناس حقيقة النعمة، فما هي؟\nوَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ ٢٠ وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ ٢١\n﴿وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةًۖ﴾: بيان للنعم الواصلة إليهم من جهة الحيوان إثر بيان النعم الفائضة من جهة الماء والنبات. الألوسي:٩/٢٢٥.\nلماذا بدأ بنعمة الماء والنبات قبل نعمة الأنعام؟\nفَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ٢٤ إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ\nوهذه الشُّبَه التي أوردوها... هي في نفسها متناقضة متعارضة؛ فقوله: ﴿مَا هَٰذَآ إِلَّا بَشَرٌ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ﴾ أثبتوا أن له عقلًا يكيدهم به ليعلوهم ويسودهم، ويحتاج مع هذا أن يحذر منه لئلَّا يغتر به، فكيف يلتئم مع قولهم: ﴿إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٌ﴾؟! السعدي:٥٥٠.\nبيّن التناقض والتعارض الموجود في كلامهم.\nفَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ٢٤\nاستبعدوا أن تكون النبوّة لبشر؛ فيا عجبًا منهم إذ أثبتوا الربوبية لحجر! ابن جزي:٢/٧٠.\nفي استبعاد الكفار أن تكون الرسل من البشر غاية التناقض، وضح ذلك.\nفَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ٢٤\nسادة القوم ظنوا أنه ما جاء بتلك الدعوة إلاّ حبًا في أن يَسُود على قومهم؛ فَخَشُوا أن تزول سيادتهم، وهم بجهلهم لا يتدبرون أحوال النفوس، ولا ينظرون مصالح الناس، ولكنهم يقيسون غيرهم على مقياس أنفسهم. ابن عاشور:١٨/٤٢.\nحب الرئاسة والسيادة خطر على الإنسان وعلى دينه، بين ذلك من الآية الكريمة."]])